'\''20i /* The adversary: a second model beside the spear that rates the closed
 * USER and TURN entries of the log. It never acts and has no editor
 * access; the spear reads the ratings when a kind 1 checkpoint or a
 * compaction opens. It shares the spear endpoint, so one request is in
 * flight at a time and only the prompt says which task the model has.
 * A sleeper thread, not a session: it wakes when the model is free and
 * rates one entry per request, oldest first, and dies when the spear
 * takes the endpoint back. Nothing is cancelled half way, so each entry
 * is rated in a context holding nothing else, which is the point.
 * The worker blocks only in fork, waitpid and file reads, and touches no
 * nextvi state but two mutexed queues of heap strings it owns; all lbuf
 * work stays on the main thread at the input wait. Portable chat
 * completions only. */
#define ADV_RESULT_MAX 4000		/* RESULT body bytes sent per part */
#define ADV_ATTEMPTS 3			/* requests per entry, the first one */
#define ADV_REPLY_MAX (4 << 20)		/* reply bytes kept */
#define ADV_LOG_MAX 5000		/* b-9 lines kept */
#define ADV_PRIOR 64			/* earlier ratings the model may lean on */
#define ADV_IDLE 5000			/* ms free before the sleeper works */
#define ADV_QUEUE 8			/* prompts the sleeper may hold */
#define ADV_QUEUE_MAX (64 << 10)	/* prompt bytes the sleeper may hold */
#define ADV_OUT_MAX 8			/* answers kept for the main thread */
/* The topic request, whose work item carries entry number ADV_NAME: no log
 * entry has that number, since numbering starts at 1. */
#define ADV_NAME 0
#define ADV_NAME_MAX 2000		/* log bytes the name request shows */
#define ADV_NAME_WORDS 3		/* words the identifier may hold */
#define ADV_NAME_LEN 48			/* bytes of the identifier */

static char agent_adv_intro[] =
	"You are an adversarial reviewer of the session log of another model, the spear.\n"
	"You do not act and you have no access to the editor: you only rate and note.\n"
	"A USER entry is what the user wrote. A TURN entry is one spear reply\n"
	"with its REASONING, the EX commands it ran and their RESULT bodies.\n"
	"Rate the entry on the 0 to 3 scale given below.\n"
	"Do not grade on a curve and do not inflate: if the entry shows less\n"
	"than the work it claims, say so. Answering 3 to everything is a\n"
	"failure of review, not a streak of good work.\n"
	"Reply with one line and no other text that follows the format:\n"
	"N R sentence\n\n"
	"N is the entry number\n"
	"R is the rating\n"
	"sentence is one short sentence of justification.\n\n";

/* One prompt waiting for the worker, and one answer waiting for the main
 * thread: each owns the heap text it carries across. The endpoint travels
 * with the prompt, since :set endpoint= would otherwise move under a
 * request. */
struct agent_adv_work {
	unsigned long n;
	int attempt, timeout;
	char *sys, *prompt, *prev, *url, *key, *extra;
};
struct agent_adv_job { unsigned long n; char *text; int st, attempt; };

static struct {
	int on;			/* :adv is on */
	int disabled;		/* endpoint unreachable: off for the session */
	/* the worker thread owns all of these, under mtx */
	pthread_mutex_t mtx;
	pthread_cond_t cv;
	int idle;		/* the editor waits for input */
	int awake;		/* the sleeper may look for work */
	int stop;		/* the spear wants the endpoint back */
	int quit;		/* process exit */
	int thread;		/* the worker is running */
	pthread_t td;
	int busy;		/* a request is in flight */
	unsigned long epoch, seen;	/* spear activity: the sleeper'\''s timer */
	unsigned long primed;	/* epoch whose quiet run has already begun */
	struct agent_adv_work *queue;	/* prompts waiting to be asked */
	int nqueue, qmax;
	struct agent_adv_job *out;	/* answers waiting to be read */
	int nout, omax;
	int want;		/* the sleeper has run dry and wants a scan */
	unsigned long num;	/* the entry its request is about */
	int attempt;		/* requests made for num, the first one */
	/* main thread, or handed across the queues */
	pid_t pid;		/* the curl child the worker waits for */
	int fd[2];		/* curl stdout and stderr files */
	int notify[2];		/* self pipe: the input poll watches fd[0] */
	int logfd;		/* b-9 write in flight */
	char hdpath[64];	/* header file handed to curl; the worker'\''s own,
				 * the main thread never reads or unlinks it */
	int killed;		/* the main thread ended the request in flight */
	char *prev;		/* previous reply, sent as an assistant turn */
} agent_adv = {
	.primed = ~0UL,	/* so the first quiet stretch waits out ADV_IDLE */
	.pid = -1, .fd = {-1, -1}, .notify = {-1, -1}, .logfd = -1
};


/* The sleeper parts, each in the order the next one needs it. */
static void agent_adv_stop(void);
static void agent_adv_collect(void);
static int agent_adv_staged_has(unsigned long n);
static void agent_adv_help_read(void);
static void agent_adv_help_drop(void);
static int agent_adv_wanted(void);
static void agent_adv_parse(unsigned long want, const char *reply);
static char *agent_adv_sys(unsigned long n);
static char *agent_adv_prompt(unsigned long n);
int agent_adv_start(void);
void agent_adv_off(void);

/* A staged rating: not in b-6 until a checkpoint or compaction merges it. */
struct agent_adv_rating { unsigned long n; int rate; char *text; };
static struct agent_adv_rating *agent_adv_staged;
static int agent_adv_nstaged;
/* Entries given up on after ADV_ATTEMPTS malformed answers, so that they are
 * not sent forever. */
static unsigned long *agent_adv_gaveup;
static int agent_adv_ngaveup;

/* Nothing of the sleeper'\''s is the main thread'\''s to clean: what it asked
 * about it either answers or drops. */
static void agent_adv_clear(void)
{
	agent_adv.num = 0;
	agent_adv.attempt = 0;
}

/* Append s to b-9, keeping the file bounded, and let the session save it:
 * inside a tool call agent_sync defers the write to agent_sync_pending. */
static void agent_adv_log(const char *s)
{
	struct lbuf *lb = tempbufs[8].lb;
	int n = lbuf_len(lb);
	if (!*s)
		return;
	preserve(int, agent_syncing, agent_syncing = 1;)
	if (n > ADV_LOG_MAX) {
		lbuf_edit(lb, NULL, 0, n - ADV_LOG_MAX / 2, 0, 0);
		temp_pos(8, lbuf_len(lb) - 1, 0, 0);
		if (ex_buf == tempbufs+8) {
			exbuf_load(ex_buf)
		}
	}
	temp_write(8, (char *)s);
	restore(agent_syncing)
	agent_sync(lb);
}

/* A b-9 line with a printf format. */
static void agent_adv_note(const char *fmt, ...)
{
	char ln[512];
	va_list ap;
	va_start(ap, fmt);
	vsnprintf(ln, sizeof(ln), fmt, ap);
	va_end(ap);
	ln[sizeof(ln)-1] = '\''\0'\'';
	agent_adv_log(ln);
}

/* Whether set holds n. */
static int agent_adv_has(unsigned long *set, int cnt, unsigned long n)
{
	for (int i = 0; i < cnt; i++)
		if (set[i] == n)
			return 1;
	return 0;
}

/* Drop n from set, or all of it with n ~0. */
static void agent_adv_drop(unsigned long *set, int *cnt, unsigned long n)
{
	int i = 0;
	while (i < *cnt)
		if (set[i] == n || n == ~0UL)
			set[i] = set[--*cnt];
		else
			i++;
}

/* Remember n as given up on, so the adversary is not asked for it again. */
static void agent_adv_add(unsigned long **set, int *cnt, unsigned long n)
{
	if (agent_adv_has(*set, *cnt, n))
		return;
	*set = erealloc(*set, (*cnt + 1) * sizeof(**set));
	(*set)[(*cnt)++] = n;
}

/* Stage a rating for entry n, replacing a staged one: the last line wins. */
static void agent_adv_stage(unsigned long n, int rate, const char *text)
{
	struct agent_adv_rating *r = NULL;
	int i;
	for (i = 0; i < agent_adv_nstaged; i++)
		if (agent_adv_staged[i].n == n) {
			r = agent_adv_staged + i;
			break;
		}
	if (!r) {
		agent_adv_staged = erealloc(agent_adv_staged,
			(agent_adv_nstaged + 1) * sizeof(*agent_adv_staged));
		r = agent_adv_staged + agent_adv_nstaged++;
		r->n = n;
		r->text = NULL;
	}
	free(r->text);
	r->rate = rate;
	r->text = sdup(text, strlen(text));
}

static struct agent_span *agent_adv_span(struct agent_span *spans, int cnt,
		unsigned long n)
{
	for (int k = 0; k < cnt; k++)
		if (spans[k].n == n)
			return spans + k;
	return NULL;
}

/* Whether span is closed; for the last entry of the log, only while it is
 * not still being written. A part of an open TURN is never sent. */
static int agent_adv_closed(struct agent_span *s, int last)
{
	if (s->role == AE_TURN)
		return !(agent_turn[1] && s->n == agent_turn[1]) &&
			(!last || !*s->open);
	return s->close >= 0 || (!last || !*s->open);
}

/* lb lines beg through end-1 into sb, capping the body at max bytes; with
 * max 0 all of it. A cut body gets a note of the bytes dropped. */
static void agent_adv_lines(sbuf *sb, struct lbuf *lb, int beg, int end,
		int max)
{
	int all = 0, kept = 0, cut = 0, n;
	char msg[96];
	for (int i = beg; i < end; i++) {
		n = strlen(lb->ln[i]);
		all += n;
		if (max && kept + n > max) {
			if (kept < max) {
				sbuf_mem(sb, lb->ln[i], max - kept)
				sbuf_chr(sb, '\''\n'\'')
				kept = max;
			}
			cut = 1;
			continue;
		}
		kept += n;
		sbuf_str(sb, lb->ln[i])
	}
	if (cut) {
		snprintf(msg, sizeof(msg), "[... %d bytes truncated]\n",
			all - kept);
		sbuf_str(sb, msg)
	}
}

/* Entry s of lb into sb: its lines verbatim, only a RESULT body capped at
 * ADV_RESULT_MAX bytes. Headers and END lines come from the buffer, so the
 * adversary sees exactly what the log holds. */
static void agent_adv_entry(sbuf *sb, struct lbuf *lb, struct agent_span *s)
{
	struct agent_part *parts = NULL;
	int pcnt = s->role == AE_TURN ? agent_parts(lb, s, &parts) : 0, to;
	if (!pcnt) {
		agent_adv_lines(sb, lb, s->beg,
			s->close >= 0 ? s->close + 1 : s->end, 0);
		free(parts);
		return;
	}
	for (int p = 0; p < pcnt; p++) {
		sbuf_str(sb, lb->ln[parts[p].beg])
		to = parts[p].close > 0 ? parts[p].close : parts[p].end;
		agent_adv_lines(sb, lb, parts[p].beg + 1, to,
			parts[p].role == AP_RESULT ? ADV_RESULT_MAX : 0);
		if (parts[p].close > 0)
			sbuf_str(sb, lb->ln[parts[p].close])
	}
	free(parts);
}

/* Its request body: the endpoint and key the spear uses, one request in
 * flight on it. Portable chat completions only, so the spear extras go. */
static cJSON *agent_adv_config(struct agent_adv_work *w)
{
	cJSON *req = cJSON_ParseWithOpts(w->extra, NULL, 1);
	if (!cJSON_IsObject(req) || !w->key || !*w->key ||
			strpbrk(w->key, "\r\n") || !w->url ||
			(strncmp(w->url, "http://", 7) &&
			strncmp(w->url, "https://", 8)) || w->timeout <= 0) {
		cJSON_Delete(req);
		return NULL;
	}
	const char *owned[] = {"messages", "tools", "stream", "tool_choice",
		"response_format"};
	for (int i = 0; i < LEN(owned); i++)
		while (cJSON_GetObjectItem(req, owned[i]))
			cJSON_DeleteItemFromObject(req, owned[i]);
	return req;
}

/* Ratings it made already, newest ADV_PRIOR from b-6 plus the staged ones:
 * enough not to contradict itself, too few to be a context of its own. */
static void agent_adv_priors(sbuf *sb)
{
	struct lbuf *nb = tempbufs[5].lb;
	unsigned long floor = agent_epoch_floor(), m;
	char head[32];
	int keep[ADV_PRIOR], nkeep = 0, rate;
	sbuf_str(sb, "\nPrevious ratings:\n")
	for (int i = 0; i < lbuf_len(nb); i++)
		if (agent_note_line(nb->ln[i], &m, &rate) && m >= floor) {
			if (nkeep == LEN(keep))
				memmove(keep, keep + 1,
					sizeof(keep[0]) * (LEN(keep) - 1));
			keep[nkeep++] = i;
		}
	for (int i = 0; i < nkeep; i++)
		sbuf_str(sb, nb->ln[keep[i]])
	for (int i = 0; i < agent_adv_nstaged; i++) {
		if (agent_adv_staged[i].n < floor)
			continue;
		snprintf(head, sizeof(head), "%lu %d ", agent_adv_staged[i].n,
			agent_adv_staged[i].rate);
		sbuf_str(sb, head)
		if (agent_adv_staged[i].text)
			sbuf_str(sb, agent_adv_staged[i].text)
		sbuf_chr(sb, '\''\n'\'')
	}
}

/* Its system message: what it is, how to rate, what it already decided and
 * the one line it answers with. */
static char *agent_adv_sys(unsigned long n)
{
	char head[80];
	sbuf_smake(sb, 4096)
	sbuf_str(sb, agent_adv_intro)
	sbuf_str(sb, agent_rating_scale)
	sbuf_str(sb, "R is the rating, one of 0, 1, 2 or 3 as defined above; "
		"no other number. Most entries are 0 or 1: answer 3 for the "
		"few the remaining work truly depends on.\n")
	agent_adv_priors(sb);
	snprintf(head, sizeof(head), "\nRate one entry, replying only with "
		"the line:\n%lu R sentence\n", n);
	sbuf_str(sb, head)
	sbufn_ret(sb, sb->s)
}

/* Its user message: the single entry under review, nothing else. */
static char *agent_adv_prompt(unsigned long n)
{
	struct lbuf *lb = tempbufs[3].lb;
	struct agent_span *spans;
	struct agent_span *s;
	int cnt = agent_spans(&spans);
	sbuf_smake(sb, 4096)
	s = agent_adv_span(spans, cnt, n);
	sbuf_str(sb, "Entry:\n")
	if (s)
		agent_adv_entry(sb, lb, s);
	sbufn_ret(sb, sb->s)
}

/* Whether a prompt for n is already on its way to the sleeper, or is the one
 * it is asking about now. */
static int agent_adv_queued(unsigned long n)
{
	int found = 0;
	pthread_mutex_lock(&agent_adv.mtx);
	for (int i = 0; i < agent_adv.nqueue; i++)
		found |= agent_adv.queue[i].n == n;
	found |= agent_adv.busy && agent_adv.num == n;
	pthread_mutex_unlock(&agent_adv.mtx);
	return found;
}

/* The oldest closed USER or TURN entry it has not rated: not in b-6, not
 * staged, not queued, not given up on, at or above the last compaction;
 * 0 when none is left. One entry per request, since a batch lets the
 * model skip part of it unseen. */
static int agent_adv_next(unsigned long *num)
{
	struct agent_span *spans;
	unsigned long floor = agent_epoch_floor(), n;
	int cnt = agent_spans(&spans), last = cnt - 1, rate, row;
	for (int k = 0; k < cnt; k++) {
		n = spans[k].n;
		if ((spans[k].role != AE_USER && spans[k].role != AE_TURN) ||
				n < floor ||
				!agent_adv_closed(spans + k, k == last) ||
				agent_note(n, &rate, &row) ||
				agent_adv_has(agent_adv_gaveup, agent_adv_ngaveup, n) ||
				agent_adv_queued(n))
			continue;
		for (int i = 0; i < agent_adv_nstaged; i++)
			if (agent_adv_staged[i].n == n)
				goto next;
		free(spans);
		*num = n;
		return 1;
	next:;
	}
	free(spans);
	return 0;
}

/* Append one prompt to the queue; agent_adv.mtx is held. */
static void agent_adv_qadd(struct agent_adv_work *w)
{
	if (agent_adv.nqueue == agent_adv.qmax) {
		agent_adv.qmax = agent_adv.qmax ? agent_adv.qmax * 2 : 8;
		agent_adv.queue = erealloc(agent_adv.queue,
			agent_adv.qmax * sizeof(*agent_adv.queue));
	}
	agent_adv.queue[agent_adv.nqueue++] = *w;
}
/* The topic request. The sleeper asks what the session is about and renames
 * its directory from the start time to "<topic>_<start time>", so that a
 * later resume or an ls of the log directory says what a session holds.
 * Asked once, of the first entries, with the same rules as a rating. */
static char agent_adv_name_intro[] =
	"You name the session log of another model, the spear.\n"
	"You have no access to the editor: you only answer with a name.\n"
	"Reply with one line and no other text that follows the format:\n"
	"T name\n\n"
	"name is two or three short words in lower case joined with\n"
	"underscores that say what the session is about, as\n"
	"blockchain_question or fix_tls_handshake.\n"
	"No spaces, no punctuation, no article, no sentence.\n";

/* Whether leaf is the name agent_start gives a session: %Y%m%d-%H%M%S, plus
 * the -N it adds when that name is taken. A directory the user named, or one
 * a topic already leads, keeps its name. */
static int agent_adv_ts_leaf(const char *leaf)
{
	if (strlen(leaf) < 15 || leaf[8] != '\''-'\'')
		return 0;
	for (int i = 0; i < 15; i++)
		if (i != 8 && !isdigit((unsigned char)leaf[i]))
			return 0;
	return !leaf[15] || leaf[15] == '\''-'\'';
}

/* Whether the session still wants a name: its directory is the start time,
 * no name was applied or given up, no request is pending, and the log holds
 * a USER entry to judge the topic from. */
static int agent_adv_name_wanted(void)
{
	struct agent_span *spans;
	char *leaf;
	int cnt, k, ok = 0;
	if (!agent_ready || agent_adv_named ||
			agent_adv_name_try >= ADV_ATTEMPTS ||
			agent_adv_queued(ADV_NAME))
		return 0;
	leaf = agent_sessdir ? strrchr(agent_sessdir, '\''/'\'') : NULL;
	if (!leaf || !agent_adv_ts_leaf(leaf + 1))
		return 0;
	cnt = agent_spans(&spans);
	for (k = 0; k < cnt; k++)
		if (spans[k].role == AE_USER) {
			ok = 1;
			break;
		}
	free(spans);
	return ok;
}

/* Its system message: what a name is, and the one line it answers with. */
static char *agent_adv_name_sys(void)
{
	sbuf_smake(sb, 1024)
	sbuf_str(sb, agent_adv_name_intro)
	sbufn_ret(sb, sb->s)
}

/* Its user message: the start of the session, capped. */
static char *agent_adv_name_prompt(void)
{
	struct lbuf *lb = tempbufs[3].lb;
	struct agent_span *spans;
	int cnt = agent_spans(&spans), bytes = 0;
	sbuf_smake(sb, 4096)
	sbuf_str(sb, "What is this session about? Its first entries:\n")
	for (int k = 0; k < cnt && bytes < ADV_NAME_MAX; k++) {
		if (spans[k].role != AE_USER)
			continue;
		agent_adv_lines(sb, lb, spans[k].beg,
			spans[k].close >= 0 ? spans[k].close + 1 : spans[k].end,
			ADV_NAME_MAX - bytes);
		bytes = sb->s_n;
	}
	free(spans);
	sbuf_str(sb, "\nReply with the name of this session.\n")
	sbufn_ret(sb, sb->s)
}
/* A token of the shape a name has: letters, digits and one underscore
 * between words. Returns the start of the run and its length, or NULL. */
static const char *agent_adv_name_tok(const char *line, int len, int *out)
{
	int i = len;
	while (i > 0) {
		int e, b, w = 0, us = 0;
		if (!(isalnum((unsigned char)line[i - 1]) ||
				line[i - 1] == '\''_'\'')) {
			i--;
			continue;
		}
		e = i;
		while (i > 0 && (isalnum((unsigned char)line[i - 1]) ||
				line[i - 1] == '\''_'\''))
			i--;
		b = i;
		for (int k = b; k < e; k++) {
			if (line[k] != '\''_'\'')
				continue;
			if (k == b || k + 1 == e || line[k + 1] == '\''_'\'')
				goto next;	/* a bad underscore */
			w++;
			us = 1;
		}
		if (e - b >= 3 && us && w + 1 <= ADV_NAME_WORDS &&
				strncmp(line + b, "name", e - b)) {
			*out = e - b;
			return line + b;
		}
next:
		i = b;
	}
	return NULL;
}

/* The identifier a name reply carries: lower case words joined with
 * underscores, at most ADV_NAME_WORDS words, or NULL. The last such token
 * wins, so prose around the answer costs nothing: a sentence has no
 * underscore between its words. The reply leads with "T"; a reply holding
 * the name alone is read as it. */
static char *agent_adv_name_parse(const char *reply)
{
	const char *s, *pick = NULL;
	char *out;
	int len, best = -1, n = 0;
	for (s = reply; s && *s; ) {
		const char *e = strchr(s, '\''\n'\'');
		int i = 0;
		const char *t;
		len = e ? (int)(e - s) : (int)strlen(s);
		while (len && (isspace((unsigned char)*s) || *s == '\''>'\'' ||
				*s == '\''#'\'' || *s == '\''*'\'' || *s == '\''`'\''))
			s++, len--;
		while (len && (isspace((unsigned char)s[len - 1]) ||
				s[len - 1] == '\''"'\'' || s[len - 1] == '\''\'\'''\'' ||
				s[len - 1] == '\''*'\'' || s[len - 1] == '\''.'\'' ||
				s[len - 1] == '\'':'\''))
			len--;
		/* the last token on the line: prose leads, the name follows */
		for (int k = len - 1; k >= 0; k--) {
			if (s[k] != '\''_'\'' && !isalnum((unsigned char)s[k]))
				continue;
			t = agent_adv_name_tok(s, k + 1, &i);
			if (t && i > best) {
				best = i;
				pick = t;
				n = i;
			}
			break;
		}
		if (!e)
			break;
		s = e + 1;
	}
	if (!pick || n > ADV_NAME_LEN)
		return NULL;
	out = emalloc(n + 1);
	for (int k = 0; k < n; k++)
		out[k] = tolower((unsigned char)pick[k]);
	out[n] = '\''\0'\'';
	return out;
}

/* Move the session directory to "<topic>_<start time>" and point b-4 to b-9
 * at it. The files keep their names, so a resume finds them under the new
 * directory. */
static int agent_adv_name_apply(const char *name)
{
	char *dir, *nw, *path, *slash;
	int i, n;
	if (!agent_sessdir || !*agent_sessdir || !name || !*name)
		return 0;
	dir = agent_sessdir;
	n = strlen(dir);
	while (n > 1 && dir[n - 1] == '\''/'\'')
		dir[--n] = '\''\0'\'';
	slash = strrchr(dir, '\''/'\'');
	if (!slash || !slash[1]) {
		agent_adv_note("cannot name the session log: no directory");
		return 0;
	}
	nw = emalloc(n + strlen(name) + strlen(slash + 1) + 3);
	sprintf(nw, "%.*s/%s_%s", (int)(slash - dir), dir, name, slash + 1);
	if (rename(dir, nw)) {
		agent_adv_note("cannot name the session log: %s",
			strerror(errno));
		free(nw);
		return 0;
	}
	for (i = 3; i < 9; i++) {
		if (!tempbufs[i].path)
			continue;
		path = emalloc(strlen(nw) + strlen(tempbufs[i].path) + 32);
		sprintf(path, "%s%s", nw, tempbufs[i].path + n);
		free(tempbufs[i].path);
		tempbufs[i].path = path;
		tempbufs[i].plen = strlen(path);
	}
	free(agent_sessdir);
	agent_sessdir = nw;
	agent_adv_named = 1;
	agent_adv_note("session log renamed to %s", nw);
	return 1;
}

/* Ask again about the topic: the same first entries, its previous answer
 * back as an assistant turn. Built on the main thread. */
static void agent_adv_name_requeue(int attempt, const char *prev)
{
	struct agent_adv_work w;
	w.n = ADV_NAME;
	w.attempt = attempt;
	w.timeout = request_timeout;
	w.sys = agent_adv_name_sys();
	w.prompt = agent_adv_name_prompt();
	w.prev = prev && *prev ? sdup(prev, strlen(prev)) : NULL;
	w.url = endpoint ? sdup(endpoint, strlen(endpoint)) : NULL;
	w.key = api_key ? sdup(api_key, strlen(api_key)) : NULL;
	w.extra = request_extra ?
		sdup(request_extra, strlen(request_extra)) : NULL;
	if (!w.sys || !w.prompt || !w.url || !w.key || !w.extra) {
		free(w.sys);
		free(w.prompt);
		free(w.prev);
		free(w.url);
		free(w.key);
		free(w.extra);
		agent_adv_named = 2;
		return;
	}
	pthread_mutex_lock(&agent_adv.mtx);
	agent_adv_qadd(&w);
	agent_adv.awake = 1;
	pthread_cond_signal(&agent_adv.cv);
	pthread_mutex_unlock(&agent_adv.mtx);
}

/* What the topic request answered: the name applied, or another try while
 * one is left. Main thread. */
static void agent_adv_name_reply(char *text, int st, int attempt)
{
	char *name = NULL, *content = NULL, *prev = NULL;
	cJSON *root, *msg;
	if (!text) {
		agent_adv_note("no reply naming the session, status %d", st);
		if (attempt + 1 >= ADV_ATTEMPTS) {
			agent_adv_named = 2;
			return;
		}
		agent_adv_name_try = attempt + 1;
		agent_adv_name_requeue(attempt + 1, NULL);
		return;
	}
	agent_adv_note("--- reply, session name, attempt %d of %d, status %d ---",
		attempt, ADV_ATTEMPTS, st);
	agent_adv_log(text);
	root = cJSON_ParseWithOpts(text, NULL, 1);
	msg = agent_reply(root);
	if (cJSON_IsString(cJSON_GetObjectItem(msg, "content")))
		content = cJSON_GetObjectItem(msg, "content")->valuestring;
	if (content) {
		name = agent_adv_name_parse(content);
		prev = sdup(content, strlen(content));
	}
	cJSON_Delete(root);
	if (name && agent_adv_name_apply(name))
		agent_adv_note("the session is named \"%s\"", name);
	else if (attempt + 1 >= ADV_ATTEMPTS) {
		agent_adv_note("no name for the session after %d attempts; "
			"giving up", ADV_ATTEMPTS);
		agent_adv_named = 2;
	}
	else {
		agent_adv_note("no name for the session; asking again");
		agent_adv_name_try = attempt + 1;
		agent_adv_name_requeue(attempt + 1, prev);
	}
	free(name);
	free(prev);
}


/* Wake the input poll: the sleeper wants prompts, or has an answer. */
static void agent_adv_nudge(void)
{
	char c = 1;
	if (agent_adv.notify[1] >= 0)
		while (write(agent_adv.notify[1], &c, 1) < 0 && errno == EINTR);
}

/* Build and queue the next prompts, ADV_QUEUE at most and ADV_QUEUE_MAX
 * bytes, so an idle stretch does not make the sleeper hoard the session.
 * Every byte of the log is read here, on the main thread. */
static void agent_adv_fill(void)
{
	struct agent_adv_work w;
	unsigned long n;
	int bytes = 0, room = ADV_QUEUE;
	pthread_mutex_lock(&agent_adv.mtx);
	for (int i = 0; i < agent_adv.nqueue; i++)
		bytes += strlen(agent_adv.queue[i].prompt);
	room -= agent_adv.nqueue;
	pthread_mutex_unlock(&agent_adv.mtx);
	/* The topic first: one answer renames the whole session, and it is
	 * the shorter ask of the two. */
	if (room > 0 && agent_adv_name_wanted()) {
		w.n = ADV_NAME;
		w.attempt = agent_adv_name_try;
		w.prev = NULL;
		w.timeout = request_timeout;
		w.sys = agent_adv_name_sys();
		w.prompt = agent_adv_name_prompt();
		w.url = endpoint ? sdup(endpoint, strlen(endpoint)) : NULL;
		w.key = api_key ? sdup(api_key, strlen(api_key)) : NULL;
		w.extra = request_extra ?
			sdup(request_extra, strlen(request_extra)) : NULL;
		if (!w.sys || !w.prompt || !w.url || !w.key || !w.extra) {
			free(w.sys);
			free(w.prompt);
			free(w.url);
			free(w.key);
			free(w.extra);
		}
		else {
			bytes += strlen(w.prompt);
			room--;
			pthread_mutex_lock(&agent_adv.mtx);
			agent_adv_qadd(&w);
			pthread_mutex_unlock(&agent_adv.mtx);
		}
	}

	while (room > 0 && bytes < ADV_QUEUE_MAX) {
		if (!agent_adv_next(&n)) {
			break;
		}
		w.n = n;
		w.attempt = 0;
		w.prev = NULL;
		w.timeout = request_timeout;
		w.sys = agent_adv_sys(n);
		w.prompt = agent_adv_prompt(n);
		w.url = endpoint ? sdup(endpoint, strlen(endpoint)) : NULL;
		w.key = api_key ? sdup(api_key, strlen(api_key)) : NULL;
		w.extra = request_extra ?
			sdup(request_extra, strlen(request_extra)) : NULL;
		if (!w.sys || !w.prompt || !w.url || !w.key || !w.extra) {
			free(w.sys);
			free(w.prompt);
			free(w.url);
			free(w.key);
			free(w.extra);
			break;
		}
		bytes += strlen(w.prompt);
		room--;
		pthread_mutex_lock(&agent_adv.mtx);
		agent_adv_qadd(&w);
		pthread_mutex_unlock(&agent_adv.mtx);
	}
}

/* Read what curl wrote, from a descriptor kept at the start of the file. */
static char *agent_adv_slurp(int fd, int max)
{
	char buf[4096];
	sbuf_smake(sb, 4096)
	ssize_t r;
	lseek(fd, 0, SEEK_SET);
	while ((r = read(fd, buf, sizeof(buf))) > 0) {
		sbuf_mem(sb, buf, (int)r)
		if (sb->s_n > max)
			break;
	}
	sbufn_ret(sb, sb->s)
}

/* Ask the model about one entry and wait, on the worker thread: answer and
 * errors go to two files, so the wait is a plain waitpid and the read a
 * plain read, with no poll and no pipe that can fill. Reply body, or NULL
 * with the curl status in *st. */
static char *agent_adv_ask(struct agent_adv_work *w, int *st)
{
	char hdrpath[] = "/tmp/nextvi-header-XXXXXX",
		bodypath[] = "/tmp/nextvi-adv-XXXXXX", timeout[32], hdrarg[96],
		dataarg[96];
	char *body = NULL, *out = NULL;
	cJSON *req = agent_adv_config(w), *arr, *msg;
	sigset_t none;
	int hf = -1, bf = -1, rc;
	pid_t pid;
	*st = -1;
	if (!req) {
		return NULL;
	}
	/* The prompt is the whole task: the rules and what it already rated as
	 * the system message, the entry alone as the user turn. A malformed
	 * answer comes back as an assistant turn on a retry, so the model
	 * corrects a line rather than starting over. */
	arr = cJSON_CreateArray();
	msg = cJSON_CreateObject();
	cJSON_AddStringToObject(msg, "role", "system");
	cJSON_AddStringToObject(msg, "content", w->sys);
	cJSON_AddItemToArray(arr, msg);
	msg = cJSON_CreateObject();
	cJSON_AddStringToObject(msg, "role", "user");
	cJSON_AddStringToObject(msg, "content", w->prompt);
	cJSON_AddItemToArray(arr, msg);
	if (w->prev) {
		msg = cJSON_CreateObject();
		cJSON_AddStringToObject(msg, "role", "assistant");
		cJSON_AddStringToObject(msg, "content", w->prev);
		cJSON_AddItemToArray(arr, msg);
	}
	cJSON_AddItemToObject(req, "messages", arr);
	body = cJSON_PrintUnformatted(req);
	cJSON_Delete(req);
	if (!body) {
		return NULL;
	}
	if (*agent_adv.hdpath)
		unlink(agent_adv.hdpath);
	hf = mkstemp(hdrpath);
	bf = mkstemp(bodypath);
	if (hf < 0 || bf < 0) {
		goto done;
	}
	sbuf_smake(hdr, 128)
	sbuf_str(hdr, "Authorization: Bearer ")
	sbuf_str(hdr, w->key)
	sbuf_chr(hdr, '\''\n'\'')
	rc = agent_writeall(hf, hdr->s, hdr->s_n);
	free(hdr->s);
	close(hf);
	hf = -1;
	if (rc) {
		goto done;
	}
	rc = agent_writeall(bf, body, strlen(body));
	snprintf(agent_adv.hdpath, sizeof(agent_adv.hdpath), "%s", hdrpath);
	close(bf);
	bf = -1;
	if (rc) {
		goto done;
	}
	if (agent_adv.fd[0] < 0) {
		/* Two templates: mkstemp rewrites its argument, so reusing one
		 * for the second file fails with EINVAL. */
		char po[] = "/tmp/nextvi-adv-out-XXXXXX";
		char pe[] = "/tmp/nextvi-adv-err-XXXXXX";
		agent_adv.fd[0] = mkstemp(po);
		unlink(po);
		agent_adv.fd[1] = mkstemp(pe);
		unlink(pe);
		if (agent_adv.fd[0] < 0 || agent_adv.fd[1] < 0) {
			goto done;
		}
	}
	ftruncate(agent_adv.fd[0], 0);
	ftruncate(agent_adv.fd[1], 0);
	lseek(agent_adv.fd[0], 0, SEEK_SET);
	lseek(agent_adv.fd[1], 0, SEEK_SET);
	snprintf(timeout, sizeof(timeout), "%d", w->timeout);
	sprintf(hdrarg, "@%s", hdrpath);
	snprintf(dataarg, sizeof(dataarg), "@%s", bodypath);
	char *argv[] = {
		"curl", "--disable", "--silent", "--show-error",
		"--fail-with-body", "--max-time", timeout, "--header", hdrarg,
		"--header", "Content-Type: application/json",
		"--data-binary", dataarg, "--url", w->url, NULL
	};
	pid = fork();
	if (!pid) {
		if (setpgid(0, 0) < 0)
			_exit(127);
		/* The worker blocks every signal so that only the main thread
		 * takes them; curl must not inherit that or it would miss the
		 * alarm behind its own timeout. */
		sigemptyset(&none);
		pthread_sigmask(SIG_SETMASK, &none, NULL);
		dup2(agent_adv.fd[0], STDOUT_FILENO);
		dup2(agent_adv.fd[1], STDERR_FILENO);
		execvp(argv[0], argv);
		_exit(127);
	}
	if (pid < 0) {
		goto done;
	}
	/* Held as the sleeper'\''s pid the instant it exists, so that a pre-empt
	 * arriving now still finds it and kills it. */
	pthread_mutex_lock(&agent_adv.mtx);
	agent_adv.pid = pid;
	pthread_mutex_unlock(&agent_adv.mtx);
	setpgid(pid, pid);
	while (waitpid(pid, &rc, 0) < 0 && errno == EINTR);
	pthread_mutex_lock(&agent_adv.mtx);
	agent_adv.pid = -1;
	pthread_mutex_unlock(&agent_adv.mtx);
	unlink(hdrpath);
	unlink(bodypath);
	*agent_adv.hdpath = '\''\0'\'';
	*st = WIFEXITED(rc) ? WEXITSTATUS(rc) : -1;
	/* Whatever came back goes to the main thread to be read and logged:
	 * on an error curl writes its complaint to stderr instead, and only
	 * there is it worth a line of b-9. */
	out = agent_adv_slurp(agent_adv.fd[0], (int)ADV_REPLY_MAX);
	if (!out || !*out) {
		free(out);
		out = agent_adv_slurp(agent_adv.fd[1], 4096);
	}
	if (!out || !*out) {
		free(out);
		return NULL;
	}
	return out;
done:
	if (hf >= 0) {
		close(hf);
		unlink(hdrpath);
	}
	if (bf >= 0) {
		close(bf);
		unlink(bodypath);
	}
	if (*agent_adv.hdpath) {
		unlink(agent_adv.hdpath);
		*agent_adv.hdpath = 0;
	}
	free(body);
	return NULL;
}

/* Drop what the sleeper holds: the spear is back and the entries are its
 * again. agent_adv.mtx is held. */
static void agent_adv_untake(void)
{
	for (int i = 0; i < agent_adv.nqueue; i++) {
		free(agent_adv.queue[i].sys);
		free(agent_adv.queue[i].prompt);
		free(agent_adv.queue[i].prev);
		free(agent_adv.queue[i].url);
		free(agent_adv.queue[i].key);
		free(agent_adv.queue[i].extra);
	}
	agent_adv.nqueue = 0;
	agent_adv.want = 0;
	agent_adv.awake = 0;
}

/* Whether the sleeper may take the next prompt without the main thread'\''s
 * leave: a quiet run is under way and prompts are queued, so the endpoint
 * goes to the next answer at once instead of idling until the next scan.
 * agent_adv.mtx is held. */
static int agent_adv_go(void)
{
	return agent_adv.idle && !agent_adv.stop &&
		agent_adv.primed == agent_adv.epoch && agent_adv.nqueue;
}

/* The sleeper thread. It waits while the spear owns the model, then after
 * ADV_IDLE without a sign of work it rates one entry per request, oldest
 * first, until the spear returns. The wait buys a quiet stretch, not each
 * request: once the run has begun an answer is followed by the next
 * submission, not by another ADV_IDLE. A request already sent is never
 * cancelled: killing curl mid-answer would leave an entry half rated, so
 * the entry goes back to the queue. */
static void *agent_adv_worker(void *unused)
{
	struct timespec ts;
	struct agent_adv_work w;
	struct agent_adv_job j;
	sigset_t all;
	char *text;
	int st, post, killed;
	(void)unused;
	sigfillset(&all);
	pthread_sigmask(SIG_SETMASK, &all, NULL);
	pthread_mutex_lock(&agent_adv.mtx);
	for (;;) {
		while (!agent_adv.quit && !agent_adv.awake && !agent_adv_go())
			pthread_cond_wait(&agent_adv.cv, &agent_adv.mtx);
		if (agent_adv.quit)
			break;
		if (agent_adv.stop) {
			agent_adv_untake();
			continue;
		}
		if (!agent_adv.idle) {
			/* active, or the editor is not at its input: sleep
			 * until either changes */
			agent_adv.awake = 0;
			continue;
		}
		if (agent_adv.primed != agent_adv.epoch) {
			/* The quiet run starts here, once per stretch: spear
			 * work bumps the epoch and this deadline is thrown away
			 * with the run, so the sleeper only acts on a stretch that
			 * went by unused. Past it primed says the run is under way,
			 * and nothing waits between two requests. */
			agent_adv.seen = agent_adv.epoch;
			clock_gettime(CLOCK_REALTIME, &ts);
			ts.tv_sec += ADV_IDLE / 1000;
			ts.tv_nsec += (long)(ADV_IDLE % 1000) * 1000000;
			if (ts.tv_nsec >= 1000000000) {
				ts.tv_sec++;
				ts.tv_nsec -= 1000000000;
			}
			while (!agent_adv.quit && !agent_adv.stop &&
					agent_adv.epoch == agent_adv.seen)
				if (pthread_cond_timedwait(&agent_adv.cv,
						&agent_adv.mtx, &ts) ==
						ETIMEDOUT)
					break;
			if (agent_adv.quit || agent_adv.stop ||
					agent_adv.epoch != agent_adv.seen)
				continue;
			agent_adv.primed = agent_adv.seen;
		}
		if (!agent_adv.nqueue) {	/* it needs prompts */
			agent_adv.want = 1;
			agent_adv.awake = 0;
			pthread_mutex_unlock(&agent_adv.mtx);
			agent_adv_nudge();
			pthread_mutex_lock(&agent_adv.mtx);
			continue;
		}
		w = agent_adv.queue[0];
		agent_adv.nqueue--;
		if (agent_adv.nqueue)
			memmove(agent_adv.queue, agent_adv.queue + 1,
				agent_adv.nqueue * sizeof(*agent_adv.queue));
		agent_adv.busy = 1;
		agent_adv.num = w.n;
		agent_adv.attempt = w.attempt;
		pthread_mutex_unlock(&agent_adv.mtx);
		text = agent_adv_ask(&w, &st);
		pthread_mutex_lock(&agent_adv.mtx);
		agent_adv.busy = 0;
		agent_adv.awake = 0;
		/* Ended by the editor'\''s return: the entry was never answered, so
		 * it goes back wanted and uncounted, with nothing said about it.
		 * Counting it would give up on an entry only because the user
		 * came back while it was being read. */
		killed = agent_adv.killed;
		agent_adv.killed = 0;
		agent_adv.want = !text || killed;
		j.n = w.n;
		j.text = text;
		j.st = st;
		j.attempt = w.attempt;
		post = !agent_adv.quit && !killed;
		if (post && agent_adv.nout == ADV_OUT_MAX) {
			free(j.text);
			post = 0;
		}
		if (post) {
			if (agent_adv.nout == agent_adv.omax) {
				agent_adv.omax = agent_adv.omax ?
					agent_adv.omax * 2 : 8;
				agent_adv.out = erealloc(agent_adv.out,
					agent_adv.omax * sizeof(*agent_adv.out));
			}
			agent_adv.out[agent_adv.nout++] = j;
		}
		pthread_mutex_unlock(&agent_adv.mtx);
		free(w.sys);
		free(w.prompt);
		free(w.prev);
		free(w.url);
		free(w.key);
		free(w.extra);
		if (post)
			agent_adv_nudge();
	}
	agent_adv_untake();
	for (int i = 0; i < agent_adv.nout; i++)
		free(agent_adv.out[i].text);
	agent_adv.nout = 0;
	pthread_mutex_unlock(&agent_adv.mtx);
	return NULL;
}

/* Ask again about an entry whose answer did not parse: same entry, its
 * previous answer back as an assistant turn. Built on the main thread. */
static void agent_adv_requeue(unsigned long n, int attempt, const char *prev)
{
	struct agent_adv_work w;
	w.n = n;
	w.attempt = attempt;
	w.timeout = request_timeout;
	w.sys = agent_adv_sys(n);
	w.prompt = agent_adv_prompt(n);
	w.prev = prev && *prev ? sdup(prev, strlen(prev)) : NULL;
	w.url = endpoint ? sdup(endpoint, strlen(endpoint)) : NULL;
	w.key = api_key ? sdup(api_key, strlen(api_key)) : NULL;
	w.extra = request_extra ?
		sdup(request_extra, strlen(request_extra)) : NULL;
	if (!w.sys || !w.prompt || !w.url || !w.key || !w.extra) {
		free(w.sys);
		free(w.prompt);
		free(w.prev);
		free(w.url);
		free(w.key);
		free(w.extra);
		return;
	}
	pthread_mutex_lock(&agent_adv.mtx);
	agent_adv_qadd(&w);
	agent_adv.awake = 1;
	pthread_cond_signal(&agent_adv.cv);
	pthread_mutex_unlock(&agent_adv.mtx);
}

/* What the sleeper answered, oldest first: raw text to b-9, rating staged,
 * another try while the entry is still worth asking. Main thread. */
static void agent_adv_collect(void)
{
	struct agent_adv_job *js;
	cJSON *root, *msg;
	unsigned long n;
	char *content;
	int cnt, st, attempt, i;
	pthread_mutex_lock(&agent_adv.mtx);
	js = agent_adv.out;
	cnt = agent_adv.nout;
	agent_adv.out = NULL;
	agent_adv.nout = agent_adv.omax = 0;
	agent_adv.want = 0;
	pthread_mutex_unlock(&agent_adv.mtx);
	for (i = 0; i < cnt; i++) {
		n = js[i].n;
		st = js[i].st;
		attempt = js[i].attempt;
		/* The topic answer names the session; it rates nothing. */
		if (n == ADV_NAME) {
			agent_adv_name_reply(js[i].text, st, attempt);
			free(js[i].text);
			continue;
		}
		agent_adv.num = n;
		agent_adv.attempt = attempt;
		if (!js[i].text) {
			if (st == 7) {
				agent_adv_note("endpoint unreachable; "
					":adv off for this session");
				agent_adv.disabled = 1;
				agent_adv_stop();
				i++;	/* the rest are not looked at */
				break;
			}
			agent_adv_note("no reply for entry %lu, status %d",
				n, st);
			if (attempt + 1 < ADV_ATTEMPTS)
				agent_adv_requeue(n, attempt + 1, NULL);
			else
				agent_adv_note("no reply for %lu after %d "
					"attempts; giving up", n,
					ADV_ATTEMPTS);
			free(js[i].text);
			continue;
		}
		agent_adv_note("--- reply, entry %lu, attempt %d of %d, "
			"status %d ---", n, attempt, ADV_ATTEMPTS, st);
		agent_adv_log(js[i].text);
		root = cJSON_ParseWithOpts(js[i].text, NULL, 1);
		if (cJSON_GetObjectItem(root, "error")) {
			char *em = cJSON_GetStringValue(cJSON_GetObjectItem(
				cJSON_GetObjectItem(root, "error"),
				"message"));
			agent_adv_note("endpoint error: %s",
				em ? em : "no message");
			cJSON_Delete(root);
			free(js[i].text);
			continue;
		}
		content = NULL;
		msg = agent_reply(root);
		if (cJSON_IsString(cJSON_GetObjectItem(msg, "content")))
			content = cJSON_GetObjectItem(msg,
				"content")->valuestring;
		agent_adv_parse(n, content);
		/* The spear may have rated the entry itself or compacted it
		 * away while the request ran. */
		if (!agent_adv_wanted())
			agent_adv_note("entry %lu already rated or gone; "
				"nothing staged", n);
		else if (agent_adv_staged_has(n))
			agent_adv_note("staged the rating for entry %lu", n);
		else if (attempt + 1 < ADV_ATTEMPTS) {
			agent_adv_note("no rating for %lu; asking again", n);
			agent_adv_requeue(n, attempt + 1, content);
		}
		else
			agent_adv_note("no rating for %lu after %d attempts; "
				"giving up", n, ADV_ATTEMPTS);
		if (!agent_adv_staged_has(n) && attempt + 1 >= ADV_ATTEMPTS &&
				agent_adv_wanted())
			agent_adv_add(&agent_adv_gaveup, &agent_adv_ngaveup, n);
		cJSON_Delete(root);
		free(js[i].text);
	}
	for (; i < cnt; i++)	/* left over by a disabled endpoint */
		free(js[i].text);
	free(js);
}

static int agent_adv_staged_has(unsigned long n)
{
	for (int i = 0; i < agent_adv_nstaged; i++)
		if (agent_adv_staged[i].n == n)
			return 1;
	return 0;
}

/* Stage the rating a reply carries. Models wrap the answer in prose, so
 * lines that are not a rating are ignored, and markdown or the separators
 * after a number are stripped. The entry number is advisory, the model
 * echoing an earlier one as often as the one asked about: an exact match
 * wins, and a reply with one rating for anything else is read as it. */
static void agent_adv_parse(unsigned long want, const char *reply)
{
	char ln[2048], *p, *q, *d, *alt = NULL;
	const char *s = reply, *text;
	unsigned long n, altn = 0;
	int len, rate, altrate = 0, nalt = 0, exact = 0;
	while (s && *s) {
		const char *nl = strchr(s, '\''\n'\'');
		len = nl ? (int)(nl - s) : (int)strlen(s);
		if (len > (int)sizeof(ln) - 1)
			len = sizeof(ln) - 1;
		memcpy(ln, s, len);
		ln[len] = '\''\0'\'';
		s = nl ? nl + 1 : NULL;
		p = ln;
		while (*p == '\'' '\'' || *p == '\''\t'\'' || *p == '\''-'\'' || *p == '\''*'\'' ||
				*p == '\''>'\'' || *p == '\''`'\'' || *p == '\''#'\'')
			p++;
		n = strtoul(p, &q, 10);
		if (q == p)
			continue;
		d = q;
		while (*d == '\'' '\'' || *d == '\''\t'\'' || *d == '\'':'\'' || *d == '\''='\'' ||
				*d == '\''*'\'' || *d == '\''`'\'' || *d == '\''.'\'' || *d == '\'')'\'')
			d++;
		if (!isdigit((unsigned char)*d) || d[1] > '\'' '\'')
			d = NULL;
		else if (*d > '\''3'\'') {
			agent_adv_note("entry %lu: rating %c is off the 0 to 3 "
				"scale", want, *d);
			continue;
		}
		/* "2 sentence": the rating with its entry number left off. */
		if (!d && q == p + 1 && *p <= '\''3'\'' && (*q == '\'' '\'' || *q == '\''\t'\'')) {
			d = p;
			n = 0;
		}
		if (!d)
			continue;
		rate = *d - '\''0'\'';
		text = d + 1 + strspn(d + 1, " \t");
		if (n == want) {
			agent_adv_stage(want, rate, text);
			exact = 1;
			continue;
		}
		nalt++;
		altrate = rate;
		altn = n;
		free(alt);
		alt = sdup(text, strlen(text));
	}
	if (exact || nalt != 1) {
		free(alt);
		return;
	}
	/* The lone rating names an entry the model echoed instead, or it left
	 * the number off: the entry asked about is the only other thing the
	 * reply can mean, and asking again buys nothing. */
	if (altn)
		agent_adv_note("entry %lu: took its lone rating %d for "
			"entry %lu", want, altrate, altn);
	else
		agent_adv_note("entry %lu: took its lone rating, which "
			"names no entry", want);
	agent_adv_stage(want, altrate, alt);
	free(alt);
}

/* Whether the entry under review still wants a rating: the spear may have
 * rated it, or a compaction dropped it, while the request ran. */
static int agent_adv_wanted(void)
{
	struct agent_span *spans;
	unsigned long floor = agent_epoch_floor();
	int cnt = agent_spans(&spans), rate, row;
	int keep = agent_adv.num >= floor &&
		agent_span_rated(spans, cnt, agent_adv.num) &&
		!agent_note(agent_adv.num, &rate, &row);
	free(spans);
	return keep;
}

/* A descriptor the main loop must never wait on. */
static void agent_adv_nb(int fd)
{
	int fl = fcntl(fd, F_GETFL, 0);
	if (fl >= 0)
		fcntl(fd, F_SETFL, fl | O_NONBLOCK);
}

/* The input wait returned: take what the sleeper sent and, if the model is
 * still free, give it more to do. */
void agent_adv_service(void)
{
	char buf[64];
	if (!agent_adv.on || agent_adv.disabled || agent_adv.stop)
		return;
	while (agent_adv.notify[0] >= 0 &&
			read(agent_adv.notify[0], buf, sizeof(buf)) > 0);
	agent_adv_collect();
	if (!agent_adv.on || agent_adv.disabled || agent_adv.stop)
		return;
	pthread_mutex_lock(&agent_adv.mtx);
	if (agent_adv.want || agent_adv.nqueue == 0)
		agent_adv.awake = 1;
	pthread_mutex_unlock(&agent_adv.mtx);
	agent_adv_fill();
	pthread_mutex_lock(&agent_adv.mtx);
	if (agent_adv.nqueue)
		agent_adv.awake = 1;
	if (agent_adv.awake)
		pthread_cond_signal(&agent_adv.cv);
	pthread_mutex_unlock(&agent_adv.mtx);
}

/* Entering or leaving the input wait. Leaving is work of its own, so a
 * request in flight is killed here rather than waited for: the session has
 * the endpoint back the moment it wants it, and the worker reaps the child
 * with the entry back on the queue. */
void agent_adv_wait(int on)
{
	if (!agent_adv.on)
		return;
	/* A runner left behind by a ^Z answers while the editor is
	 * stopped: what it answered is taken up here, so a rating the
	 * model finished during the suspend is staged at the first wait
	 * back and is never left sitting in a file. */
	agent_adv_help_read();
	pthread_mutex_lock(&agent_adv.mtx);
	agent_adv.idle = on;
	if (on) {
		if (!agent_adv.stop && !agent_adv.disabled)
			agent_adv.awake = 1;
		pthread_cond_signal(&agent_adv.cv);
	}
	else {
		agent_adv.epoch++;
		agent_adv.awake = 0;
		/* The session is back to its own work, so a request the sleeper
		 * still has waiting is ended here rather than waited for: the
		 * endpoint is the session'\''s the moment it wants it. The worker
		 * reaps it and drops the half answer; the entry is asked again
		 * in the next downtime. The pid is read and cleared under the
		 * mutex, so it is never a process that has already been reaped.
		 */
		if (agent_adv.pid > 0) {
			agent_adv.killed = 1;
			kill(-agent_adv.pid, SIGKILL);
		}
		pthread_cond_broadcast(&agent_adv.cv);
	}
	pthread_mutex_unlock(&agent_adv.mtx);
}

/* The self-pipe the input poll watches, or -1 when the sleeper is off. */
int agent_adv_fd(void)
{
	return agent_adv.on && !agent_adv.disabled ? agent_adv.notify[0] : -1;
}

/* The spear used the model or the editor: the sleeper'\''s quiet run has to
 * start over from now. */
void agent_adv_activity(void)
{
	pthread_mutex_lock(&agent_adv.mtx);
	agent_adv.epoch++;
	agent_adv.awake = 0;
	pthread_cond_broadcast(&agent_adv.cv);
	pthread_mutex_unlock(&agent_adv.mtx);
}

/* The spear is back: stop the sleeper and kill the request it has waiting.
 * Called on input, on a tool, on a resume and when :adv goes off. */
static void agent_adv_stop(void)
{
	pid_t pid;
	pthread_mutex_lock(&agent_adv.mtx);
	agent_adv.stop = 1;
	agent_adv.idle = 0;
	agent_adv.awake = 0;
	agent_adv.epoch++;
	pid = agent_adv.pid;
	if (pid > 0)
		agent_adv.killed = 1;
	pthread_mutex_unlock(&agent_adv.mtx);
	if (pid > 0)
		kill(-pid, SIGKILL);
}

/* :adv on and off. */
void agent_adv_toggle(int on)
{
	if (on)
		agent_adv_start();
	else
		agent_adv_off();
}

#define ADV_HELP 4			/* requests a stopped editor may finish */

/* A stopped editor cannot rate: SIGSTOP takes every thread, and ^Z reaches
 * the curl child in the foreground group. So the quiet run goes on in a
 * process of its own, in its own group, out of reach of both: it takes the
 * prompts the sleeper had queued, waits, asks, and leaves each answer in a
 * file; only the reading, the b-9 line and the staging wait for the return,
 * which is the next input wait. Forked after the worker is joined, so the
 * child copies a heap with one thread in it. */
struct agent_adv_help {
	pid_t pid;
	int njob;
	struct {
		unsigned long n;
		int attempt, got, timeout;
		char path[64], out[64], st[64];
	} j[ADV_HELP];
};
static struct agent_adv_help agent_help = { .pid = -1 };

/* A string with its length first, so that newlines inside it mean nothing. */
static void agent_adv_wstr(FILE *f, const char *s)
{
	size_t l = s ? strlen(s) : 0;
	if (fprintf(f, "%zu\n", l) >= 0 && l)
		fwrite(s, 1, l, f);
}

static char *agent_adv_rstr(FILE *f)
{
	size_t l;
	char *s;
	if (fscanf(f, "%zu", &l) != 1 || l > (size_t)ADV_REPLY_MAX)
		return NULL;
	if (!(s = malloc(l + 1)))
		return NULL;
	if (l && fread(s, 1, l, f) != l) {
		free(s);
		return NULL;
	}
	s[l] = '\''\0'\'';
	return s;
}

/* The runner'\''s job: one entry, in a file only this user can read, which owns
 * the name mkstemp made. */
static int agent_adv_help_job(struct agent_adv_work *w, int i)
{
	struct agent_adv_help *h = &agent_help;
	char tmpl[] = "/tmp/nextvi-advrun-XXXXXX";
	FILE *f;
	int fd = mkstemp(tmpl);
	if (fd < 0)
		return 0;
	close(fd);
	snprintf(h->j[i].path, sizeof(h->j[i].path), "%s", tmpl);
	snprintf(h->j[i].out, sizeof(h->j[i].out), "%s.out", tmpl);
	snprintf(h->j[i].st, sizeof(h->j[i].st), "%s.st", tmpl);
	h->j[i].n = w->n;
	h->j[i].attempt = w->attempt;
	h->j[i].timeout = w->timeout;
	h->j[i].got = 0;
	if (!(f = fopen(tmpl, "w"))) {
		unlink(tmpl);
		return 0;
	}
	agent_adv_wstr(f, w->sys);
	agent_adv_wstr(f, w->prompt);
	agent_adv_wstr(f, w->prev);
	agent_adv_wstr(f, w->url);
	agent_adv_wstr(f, w->key);
	agent_adv_wstr(f, w->extra);
	fclose(f);
	return 1;
}

/* What the sleeper'\''s thread does with a prompt, done here instead: quiet
 * first, then the request, then the answer where the editor will find it. */
static void agent_adv_help_run(int n)
{
	struct timespec ts;
	char num[24];
	struct agent_adv_work j;
	struct agent_adv_help *h = &agent_help;
	FILE *f;
	char *text;
	int i, st, fd;
	/* The fork shares the sleeper'\''s curl file description and header name,
	 * so the runner asks through temp files of its own, in its own group. */
	agent_adv.fd[0] = agent_adv.fd[1] = -1;
	*agent_adv.hdpath = 0;
	setpgid(0, 0);
	signal(SIGTTOU, SIG_IGN);
	signal(SIGTTIN, SIG_IGN);
	signal(SIGHUP, SIG_IGN);
	signal(SIGINT, SIG_IGN);
	for (i = 0; i < n; i++) {
		ts.tv_sec = ADV_IDLE / 1000;
		ts.tv_nsec = (long)(ADV_IDLE % 1000) * 1000000;
		nanosleep(&ts, NULL);
		if (!(f = fopen(h->j[i].path, "r")))
			break;
		j.n = h->j[i].n;
		j.attempt = h->j[i].attempt;
		j.timeout = h->j[i].timeout;
		j.sys = agent_adv_rstr(f);
		j.prompt = agent_adv_rstr(f);
		j.prev = agent_adv_rstr(f);
		j.url = agent_adv_rstr(f);
		j.key = agent_adv_rstr(f);
		j.extra = agent_adv_rstr(f);
		fclose(f);
		unlink(h->j[i].path);
		text = j.sys && j.prompt && j.url && j.key ?
			agent_adv_ask(&j, &st) : NULL;
		if (text && (fd = open(h->j[i].out,
				O_WRONLY | O_CREAT | O_TRUNC, 0600)) >= 0) {
			agent_writeall(fd, text, strlen(text));
			close(fd);
		}
		snprintf(num, sizeof(num), "%d\n", text ? st : -1);
		if ((fd = open(h->j[i].st,
				O_WRONLY | O_CREAT | O_TRUNC, 0600)) >= 0) {
			agent_writeall(fd, num, strlen(num));
			close(fd);
		}
		free(text);
		free(j.sys);
		free(j.prompt);
		free(j.prev);
		free(j.url);
		free(j.key);
		free(j.extra);
	}
	for (; i < n; i++)
		unlink(h->j[i].path);
	_exit(0);
}

/* Hand the queued prompts to a runner of its own and let the sleeper rest:
 * while the editor is stopped the runner is the only thing that asks. */
void agent_adv_suspend(void)
{
	struct agent_adv_help *h = &agent_help;
	struct agent_adv_work take[ADV_HELP];
	int i, n = 0;
	if (!agent_adv.on || agent_adv.disabled || h->pid > 0)
		return;
	agent_adv_fill();
	pthread_mutex_lock(&agent_adv.mtx);
	n = (int)(sizeof(take) / sizeof(*take));
	if (n > agent_adv.nqueue)
		n = agent_adv.nqueue;
	for (i = 0; i < n; i++) {
		if (!agent_adv_help_job(&agent_adv.queue[i], i))
			break;
		take[i] = agent_adv.queue[i];
	}
	n = i;
	h->njob = n;
	agent_adv.nqueue -= n;
	if (agent_adv.nqueue)
		memmove(agent_adv.queue, agent_adv.queue + n,
			agent_adv.nqueue * sizeof(*agent_adv.queue));
	pthread_mutex_unlock(&agent_adv.mtx);
	agent_adv_stop();
	agent_adv_halt();	/* one thread left when the child is forked */
	if (n <= 0)
		return;
	h->pid = fork();
	if (!h->pid)
		agent_adv_help_run(n);	/* does not return */
	if (h->pid < 0)
		agent_adv_help_drop();
	else
		setpgid(h->pid, h->pid);
	for (i = 0; i < n; i++) {	/* the child has a copy of its own */
		free(take[i].sys);
		free(take[i].prompt);
		free(take[i].prev);
		free(take[i].url);
		free(take[i].key);
		free(take[i].extra);
	}
}

/* Kill the runner and its group and remove what it left; an entry it never
 * got to is unrated, as after a pre-empt. */
static void agent_adv_help_drop(void)
{
	struct agent_adv_help *h = &agent_help;
	int i;
	if (h->pid <= 0)
		return;
	kill(-h->pid, SIGKILL);
	waitpid(h->pid, NULL, 0);
	for (i = 0; i < h->njob; i++) {
		unlink(h->j[i].path);
		unlink(h->j[i].out);
		unlink(h->j[i].st);
	}
	h->pid = -1;
	h->njob = 0;
}

/* Answers the runner left behind: staged at the first wait back, like an
 * answer from the sleeper'\''s own thread. */
static void agent_adv_help_read(void)
{
	struct agent_adv_help *h = &agent_help;
	struct agent_adv_job j;
	char num[24];
	FILE *f;
	int i, fd, gone;
	if (h->pid <= 0)
		return;
	gone = waitpid(h->pid, NULL, WNOHANG) != 0;
	for (i = 0; i < h->njob; i++) {
		if (h->j[i].got || !(f = fopen(h->j[i].st, "r")))
			continue;
		if (fscanf(f, "%23s", num) != 1)
			*num = '\''\0'\'';
		fclose(f);
		j.n = h->j[i].n;
		j.attempt = h->j[i].attempt;
		j.st = *num ? atoi(num) : -1;
		j.text = NULL;
		if ((fd = open(h->j[i].out, O_RDONLY)) >= 0) {
			j.text = agent_adv_slurp(fd, (int)ADV_REPLY_MAX);
			close(fd);
		}
		unlink(h->j[i].out);
		unlink(h->j[i].st);
		h->j[i].got = 1;
		pthread_mutex_lock(&agent_adv.mtx);
		if (agent_adv.nout < ADV_OUT_MAX) {
			if (agent_adv.nout == agent_adv.omax) {
				agent_adv.omax = agent_adv.omax ?
					agent_adv.omax * 2 : 8;
				agent_adv.out = erealloc(agent_adv.out,
					agent_adv.omax *
					sizeof(*agent_adv.out));
			}
			agent_adv.out[agent_adv.nout++] = j;
		}
		else
			free(j.text);
		pthread_mutex_unlock(&agent_adv.mtx);
	}
	if (!gone)
		return;
	for (i = 0; i < h->njob; i++)
		if (!h->j[i].got) {
			unlink(h->j[i].path);
			unlink(h->j[i].out);
			unlink(h->j[i].st);
		}
	h->pid = -1;
	h->njob = 0;
}

/* Back from a suspend: the runner'\''s answers are taken at the input wait
 * itself, so all that is left is to give the sleeper its thread again. */
void agent_adv_resume(void)
{
	if (agent_adv.on)
		agent_adv_start();
}

/* Take the model back: the sleeper sleeps again and everything it holds is
 * dropped, because an entry it never asked about is the spear'\''s to rate. */
void agent_adv_preempt(void)
{
	if (!agent_adv.on)
		return;
	/* a runner from a ^Z gives the endpoint back the same way:
	 * an entry it never got to is the spear'\''s to rate. */
	agent_adv_help_drop();
	agent_adv_stop();
}

/* Start the sleeper once per session; :adv may be turned off and on again
 * without another thread. */
int agent_adv_start(void)
{
	if (agent_adv.notify[1] < 0 && pipe(agent_adv.notify))
		return 0;
	agent_adv_nb(agent_adv.notify[0]);
	if (!agent_adv.thread) {
		agent_adv.stop = 0;
		agent_adv.disabled = 0;
		agent_adv.quit = 0;	/* halt left it set: the thread would exit */
		if (pthread_create(&agent_adv.td, NULL, agent_adv_worker,
				NULL))
			return 0;
		agent_adv.thread = 1;
	}
	agent_adv.on = 1;
	agent_adv.stop = 0;
	pthread_mutex_lock(&agent_adv.mtx);
	agent_adv.awake = 1;
	agent_adv.seen = agent_adv.epoch;
	pthread_cond_signal(&agent_adv.cv);
	pthread_mutex_unlock(&agent_adv.mtx);
	agent_adv_nudge();
	return 1;
}

/* :adv off, and exit. */
void agent_adv_off(void)
{
	agent_adv.on = 0;
	/* :adv off leaves nothing asking behind, runner included */
	agent_adv_help_drop();
	agent_adv_stop();
	agent_adv_clear();
}

void agent_adv_halt(void)
{
	/* a runner left by a ^Z is not left running behind the editor */
	agent_adv_help_drop();
	if (!agent_adv.thread)
		return;
	pthread_mutex_lock(&agent_adv.mtx);
	agent_adv.quit = 1;
	agent_adv.awake = 1;
	pthread_cond_broadcast(&agent_adv.cv);
	pthread_mutex_unlock(&agent_adv.mtx);
	if (agent_adv.pid > 0)
		kill(-agent_adv.pid, SIGKILL);
	pthread_join(agent_adv.td, NULL);
	agent_adv.thread = 0;
}

/* A kind 1 checkpoint or compaction opens: staged ratings go into b-6,
 * skipping entries the spear rated itself; note_set never trims, so a 0
 * removes nothing. */
static void agent_adv_merge(void)
{
	struct agent_span *spans;
	struct lbuf *lb = tempbufs[5].lb;
	unsigned long floor = agent_epoch_floor();
	int cnt = agent_spans(&spans), rate, row, n = 0;
	if (!agent_adv_nstaged) {
		free(spans);
		return;
	}
	preserve(int, agent_syncing, agent_syncing = 1;)
	for (int i = 0; i < agent_adv_nstaged; i++) {
		if (agent_adv_staged[i].n < floor ||
				!agent_span_rated(spans, cnt, agent_adv_staged[i].n) ||
				agent_note(agent_adv_staged[i].n, &rate, &row))
			continue;
		agent_note_set(agent_adv_staged[i].n, agent_adv_staged[i].rate,
			agent_adv_staged[i].text ? agent_adv_staged[i].text : "");
		n++;
	}
	restore(agent_syncing)
	free(spans);
	for (int i = 0; i < agent_adv_nstaged; i++)
		free(agent_adv_staged[i].text);
	agent_adv_nstaged = 0;
	if (n) {
		agent_adv_note("merged %d staged rating%s into b-6", n,
			n == 1 ? "" : "s");
		agent_sync(lb);
	}
}

/* Checkpoint ended, log compacted or resumed: drop staged ratings and
 * giveups for entries the log no longer holds. */
static void agent_adv_resync(void)
{
	struct agent_span *spans;
	unsigned long floor = agent_epoch_floor();
	int cnt = agent_spans(&spans), i = 0, n = 0;
	while (i < agent_adv_nstaged) {
		if (agent_adv_staged[i].n < floor ||
				!agent_span_rated(spans, cnt, agent_adv_staged[i].n)) {
			free(agent_adv_staged[i].text);
			agent_adv_staged[i] = agent_adv_staged[--agent_adv_nstaged];
			n++;
			continue;
		}
		i++;
	}
	for (i = 0; i < agent_adv_ngaveup; ) {
		if (agent_adv_gaveup[i] < floor ||
				!agent_span_rated(spans, cnt, agent_adv_gaveup[i]))
			agent_adv_drop(agent_adv_gaveup, &agent_adv_ngaveup,
				agent_adv_gaveup[i]);
		else
			i++;
	}
	free(spans);
	if (n)
		agent_adv_note("dropped %d staged rating%s no longer live", n,
			n == 1 ? "" : "s");
}
