		agent_adv_service();
		ufd[0] = term_ufd;
		naf = agent_adv_fd();
		ufd[1].fd = naf;
		ufd[1].events = POLLIN;
		ufd[1].revents = 0;
		n = poll(ufd, naf >= 0 ? 2 : 1, -1);
				/* the sleeper'\''s byte is not input: collect and sleep again */
	} while (n > 0 && !ufd[0].revents);
	agent_adv_wait(0);
	return n;
}

