+/* Entry s of lb into sb: its lines verbatim, only a RESULT body capped at
+ * ADV_RESULT_MAX bytes. Headers and END lines come from the buffer, so the
+ * adversary sees exactly what the log holds. */
+static void agent_adv_entry(sbuf *sb, struct lbuf *lb, struct agent_span *s)
+{
+	struct agent_part *parts = NULL;
+	int pcnt = s->role == AE_TURN ? agent_parts(lb, s, &parts) : 0, to;
+	if (!pcnt) {
+		agent_adv_lines(sb, lb, s->beg,
+			s->close >= 0 ? s->close + 1 : s->end, 0);
+		free(parts);
+		return;
+	}
+	for (int p = 0; p < pcnt; p++) {
+		sbuf_str(sb, lb->ln[parts[p].beg])
+		to = parts[p].close > 0 ? parts[p].close : parts[p].end;
+		agent_adv_lines(sb, lb, parts[p].beg + 1, to,
+			parts[p].role == AP_RESULT ? ADV_RESULT_MAX : 0);
+		if (parts[p].close > 0)
+			sbuf_str(sb, lb->ln[parts[p].close])
