+/* Its user message: the start of the session, capped. */
+static char *agent_adv_name_prompt(void)
+{
+	struct lbuf *lb = tempbufs[3].lb;
+	struct agent_span *spans;
+	int cnt = agent_spans(&spans), bytes = 0;
+	sbuf_smake(sb, 4096)
