+/* The identifier a name reply carries: lower case words joined with
+ * underscores, at most ADV_NAME_WORDS words, or NULL. The last such token
+ * wins, so prose around the answer costs nothing: a sentence has no
+ * underscore between its words. The reply leads with "T"; a reply holding
+ * the name alone is read as it. */
+static char *agent_adv_name_parse(const char *reply)
+{
+	const char *s, *pick = NULL;
+	char *out;
+	int len, best = -1, n = 0;
+	for (s = reply; s && *s; ) {
+		const char *e = strchr(s, '\n');
+		int i = 0;
+		const char *t;
+		len = e ? (int)(e - s) : (int)strlen(s);
+		while (len && (isspace((unsigned char)*s) || *s == '>' ||
+				*s == '#' || *s == '*' || *s == '`'))
+			s++, len--;
+		while (len && (isspace((unsigned char)s[len - 1]) ||
+				s[len - 1] == '"' || s[len - 1] == '\'' ||
+				s[len - 1] == '*' || s[len - 1] == '.' ||
+				s[len - 1] == ':'))
+			len--;
+		/* the last token on the line: prose leads, the name follows */
+		for (int k = len - 1; k >= 0; k--) {
+			if (s[k] != '_' && !isalnum((unsigned char)s[k]))
+				continue;
+			t = agent_adv_name_tok(s, k + 1, &i);
+			if (t && i > best) {
+				best = i;
+				pick = t;
+				n = i;
+			}
+			break;
+		}
+		if (!e)
+			break;
+		s = e + 1;
+	}
+	if (!pick || n > ADV_NAME_LEN)
+		return NULL;
+	out = emalloc(n + 1);
+	for (int k = 0; k < n; k++)
+		out[k] = tolower((unsigned char)pick[k]);
+	out[n] = '\0';
+	return out;
+}
+
+/* Move the session directory to "<topic>_<start time>" and point b-4 to b-9
+ * at it. The files keep their names, so a resume finds them under the new
+ * directory. */
+static int agent_adv_name_apply(const char *name)
+{
+	char *dir, *nw, *path, *slash;
+	int i, n;
+	if (!agent_sessdir || !*agent_sessdir || !name || !*name)
+		return 0;
+	dir = agent_sessdir;
+	n = strlen(dir);
+	while (n > 1 && dir[n - 1] == '/')
+		dir[--n] = '\0';
+	slash = strrchr(dir, '/');
+	if (!slash || !slash[1]) {
+		agent_adv_note("cannot name the session log: no directory");
+		return 0;
+	}
+	nw = emalloc(n + strlen(name) + strlen(slash + 1) + 3);
+	sprintf(nw, "%.*s/%s_%s", (int)(slash - dir), dir, name, slash + 1);
+	if (rename(dir, nw)) {
+		agent_adv_note("cannot name the session log: %s",
+			strerror(errno));
+		free(nw);
+		return 0;
+	}
+	for (i = 3; i < 9; i++) {
+		if (!tempbufs[i].path)
+			continue;
+		path = emalloc(strlen(nw) + strlen(tempbufs[i].path) + 32);
+		sprintf(path, "%s%s", nw, tempbufs[i].path + n);
+		free(tempbufs[i].path);
+		tempbufs[i].path = path;
+		tempbufs[i].plen = strlen(path);
+	}
+	free(agent_sessdir);
+	agent_sessdir = nw;
+	agent_adv_named = 1;
+	agent_adv_note("session log renamed to %s", nw);
+	return 1;
+}
+
+/* Ask again about the topic: the same first entries, its previous answer
+ * back as an assistant turn. Built on the main thread. */
+static void agent_adv_name_requeue(int attempt, const char *prev)
+{
+	struct agent_adv_work w;
+	w.n = ADV_NAME;
+	w.attempt = attempt;
+	w.timeout = request_timeout;
+	w.sys = agent_adv_name_sys();
+	w.prompt = agent_adv_name_prompt();
+	w.prev = prev && *prev ? sdup(prev, strlen(prev)) : NULL;
+	w.url = endpoint ? sdup(endpoint, strlen(endpoint)) : NULL;
+	w.key = api_key ? sdup(api_key, strlen(api_key)) : NULL;
+	w.extra = request_extra ?
+		sdup(request_extra, strlen(request_extra)) : NULL;
+	if (!w.sys || !w.prompt || !w.url || !w.key || !w.extra) {
+		free(w.sys);
+		free(w.prompt);
+		free(w.prev);
+		free(w.url);
+		free(w.key);
+		free(w.extra);
+		agent_adv_named = 2;
+		return;
+	}
+	pthread_mutex_lock(&agent_adv.mtx);
+	agent_adv_qadd(&w);
+	agent_adv.awake = 1;
+	pthread_cond_signal(&agent_adv.cv);
+	pthread_mutex_unlock(&agent_adv.mtx);
+}
+
+/* What the topic request answered: the name applied, or another try while
+ * one is left. Main thread. */
+static void agent_adv_name_reply(char *text, int st, int attempt)
+{
+	char *name = NULL, *content = NULL, *prev = NULL;
+	cJSON *root, *msg;
+	if (!text) {
+		agent_adv_note("no reply naming the session, status %d", st);
+		if (attempt + 1 >= ADV_ATTEMPTS) {
+			agent_adv_named = 2;
+			return;
+		}
+		agent_adv_name_try = attempt + 1;
+		agent_adv_name_requeue(attempt + 1, NULL);
+		return;
+	}
+	agent_adv_note("--- reply, session name, attempt %d of %d, status %d ---",
+		attempt, ADV_ATTEMPTS, st);
+	agent_adv_log(text);
+	root = cJSON_ParseWithOpts(text, NULL, 1);
+	msg = agent_reply(root);
+	if (cJSON_IsString(cJSON_GetObjectItem(msg, "content")))
+		content = cJSON_GetObjectItem(msg, "content")->valuestring;
+	if (content) {
+		name = agent_adv_name_parse(content);
+		prev = sdup(content, strlen(content));
+	}
+	cJSON_Delete(root);
+	if (name && agent_adv_name_apply(name))
+		agent_adv_note("the session is named \"%s\"", name);
+	else if (attempt + 1 >= ADV_ATTEMPTS) {
+		agent_adv_note("no name for the session after %d attempts; "
+			"giving up", ADV_ATTEMPTS);
+		agent_adv_named = 2;
+	}
+	else {
+		agent_adv_note("no name for the session; asking again");
+		agent_adv_name_try = attempt + 1;
+		agent_adv_name_requeue(attempt + 1, prev);
+	}
+	free(name);
+	free(prev);
+}
+
+
+/* Wake the input poll: the sleeper wants prompts, or has an answer. */
+static void agent_adv_nudge(void)
+{
+	char c = 1;
+	if (agent_adv.notify[1] >= 0)
+		while (write(agent_adv.notify[1], &c, 1) < 0 && errno == EINTR);
+}
+
+/* Build and queue the next prompts, ADV_QUEUE at most and ADV_QUEUE_MAX
+ * bytes, so an idle stretch does not make the sleeper hoard the session.
+ * Every byte of the log is read here, on the main thread. */
+static void agent_adv_fill(void)
+{
+	struct agent_adv_work w;
+	unsigned long n;
+	int bytes = 0, room = ADV_QUEUE;
+	pthread_mutex_lock(&agent_adv.mtx);
+	for (int i = 0; i < agent_adv.nqueue; i++)
+		bytes += strlen(agent_adv.queue[i].prompt);
+	room -= agent_adv.nqueue;
+	pthread_mutex_unlock(&agent_adv.mtx);
+	/* The topic first: one answer renames the whole session, and it is
+	 * the shorter ask of the two. */
+	if (room > 0 && agent_adv_name_wanted()) {
+		w.n = ADV_NAME;
+		w.attempt = agent_adv_name_try;
+		w.prev = NULL;
+		w.timeout = request_timeout;
+		w.sys = agent_adv_name_sys();
+		w.prompt = agent_adv_name_prompt();
+		w.url = endpoint ? sdup(endpoint, strlen(endpoint)) : NULL;
+		w.key = api_key ? sdup(api_key, strlen(api_key)) : NULL;
+		w.extra = request_extra ?
+			sdup(request_extra, strlen(request_extra)) : NULL;
+		if (!w.sys || !w.prompt || !w.url || !w.key || !w.extra) {
+			free(w.sys);
+			free(w.prompt);
+			free(w.url);
+			free(w.key);
+			free(w.extra);
+		}
+		else {
+			bytes += strlen(w.prompt);
+			room--;
+			pthread_mutex_lock(&agent_adv.mtx);
+			agent_adv_qadd(&w);
+			pthread_mutex_unlock(&agent_adv.mtx);
+		}
+	}
+
+	while (room > 0 && bytes < ADV_QUEUE_MAX) {
+		if (!agent_adv_next(&n)) {
+			break;
+		}
+		w.n = n;
+		w.attempt = 0;
+		w.prev = NULL;
+		w.timeout = request_timeout;
+		w.sys = agent_adv_sys(n);
+		w.prompt = agent_adv_prompt(n);
+		w.url = endpoint ? sdup(endpoint, strlen(endpoint)) : NULL;
+		w.key = api_key ? sdup(api_key, strlen(api_key)) : NULL;
+		w.extra = request_extra ?
+			sdup(request_extra, strlen(request_extra)) : NULL;
+		if (!w.sys || !w.prompt || !w.url || !w.key || !w.extra) {
+			free(w.sys);
+			free(w.prompt);
+			free(w.url);
+			free(w.key);
+			free(w.extra);
+			break;
+		}
+		bytes += strlen(w.prompt);
+		room--;
+		pthread_mutex_lock(&agent_adv.mtx);
+		agent_adv_qadd(&w);
+		pthread_mutex_unlock(&agent_adv.mtx);
+	}
+}
+
+/* Read what curl wrote, from a descriptor kept at the start of the file. */
+static char *agent_adv_slurp(int fd, int max)
+{
+	char buf[4096];
+	sbuf_smake(sb, 4096)
+	ssize_t r;
+	lseek(fd, 0, SEEK_SET);
+	while ((r = read(fd, buf, sizeof(buf))) > 0) {
+		sbuf_mem(sb, buf, (int)r)
+		if (sb->s_n > max)
+			break;
+	}
+	sbufn_ret(sb, sb->s)
+}
+
+/* Ask the model about one entry and wait, on the worker thread: answer and
+ * errors go to two files, so the wait is a plain waitpid and the read a
+ * plain read, with no poll and no pipe that can fill. Reply body, or NULL
+ * with the curl status in *st. */
+static char *agent_adv_ask(struct agent_adv_work *w, int *st)
+{
+	char hdrpath[] = "/tmp/nextvi-header-XXXXXX",
+		bodypath[] = "/tmp/nextvi-adv-XXXXXX", timeout[32], hdrarg[96],
+		dataarg[96];
+	char *body = NULL, *out = NULL;
+	cJSON *req = agent_adv_config(w), *arr, *msg;
+	sigset_t none;
+	int hf = -1, bf = -1, rc;
+	pid_t pid;
+	*st = -1;
+	if (!req) {
+		return NULL;
+	}
+	/* The prompt is the whole task: the rules and what it already rated as
+	 * the system message, the entry alone as the user turn. A malformed
+	 * answer comes back as an assistant turn on a retry, so the model
+	 * corrects a line rather than starting over. */
+	arr = cJSON_CreateArray();
+	msg = cJSON_CreateObject();
+	cJSON_AddStringToObject(msg, "role", "system");
+	cJSON_AddStringToObject(msg, "content", w->sys);
+	cJSON_AddItemToArray(arr, msg);
+	msg = cJSON_CreateObject();
+	cJSON_AddStringToObject(msg, "role", "user");
+	cJSON_AddStringToObject(msg, "content", w->prompt);
+	cJSON_AddItemToArray(arr, msg);
+	if (w->prev) {
+		msg = cJSON_CreateObject();
+		cJSON_AddStringToObject(msg, "role", "assistant");
+		cJSON_AddStringToObject(msg, "content", w->prev);
+		cJSON_AddItemToArray(arr, msg);
+	}
+	cJSON_AddItemToObject(req, "messages", arr);
+	body = cJSON_PrintUnformatted(req);
+	cJSON_Delete(req);
+	if (!body) {
+		return NULL;
+	}
+	if (*agent_adv.hdpath)
+		unlink(agent_adv.hdpath);
+	hf = mkstemp(hdrpath);
+	bf = mkstemp(bodypath);
+	if (hf < 0 || bf < 0) {
+		goto done;
+	}
+	sbuf_smake(hdr, 128)
+	sbuf_str(hdr, "Authorization: Bearer ")
+	sbuf_str(hdr, w->key)
+	sbuf_chr(hdr, '\n')
+	rc = agent_writeall(hf, hdr->s, hdr->s_n);
+	free(hdr->s);
+	close(hf);
+	hf = -1;
+	if (rc) {
+		goto done;
+	}
+	rc = agent_writeall(bf, body, strlen(body));
+	snprintf(agent_adv.hdpath, sizeof(agent_adv.hdpath), "%s", hdrpath);
+	close(bf);
+	bf = -1;
+	if (rc) {
+		goto done;
+	}
+	if (agent_adv.fd[0] < 0) {
+		/* Two templates: mkstemp rewrites its argument, so reusing one
+		 * for the second file fails with EINVAL. */
+		char po[] = "/tmp/nextvi-adv-out-XXXXXX";
+		char pe[] = "/tmp/nextvi-adv-err-XXXXXX";
+		agent_adv.fd[0] = mkstemp(po);
+		unlink(po);
+		agent_adv.fd[1] = mkstemp(pe);
+		unlink(pe);
+		if (agent_adv.fd[0] < 0 || agent_adv.fd[1] < 0) {
+			goto done;
+		}
+	}
+	ftruncate(agent_adv.fd[0], 0);
+	ftruncate(agent_adv.fd[1], 0);
+	lseek(agent_adv.fd[0], 0, SEEK_SET);
+	lseek(agent_adv.fd[1], 0, SEEK_SET);
+	snprintf(timeout, sizeof(timeout), "%d", w->timeout);
+	sprintf(hdrarg, "@%s", hdrpath);
+	snprintf(dataarg, sizeof(dataarg), "@%s", bodypath);
+	char *argv[] = {
+		"curl", "--disable", "--silent", "--show-error",
+		"--fail-with-body", "--max-time", timeout, "--header", hdrarg,
+		"--header", "Content-Type: application/json",
+		"--data-binary", dataarg, "--url", w->url, NULL
+	};
+	pid = fork();
+	if (!pid) {
+		if (setpgid(0, 0) < 0)
+			_exit(127);
+		/* The worker blocks every signal so that only the main thread
+		 * takes them; curl must not inherit that or it would miss the
+		 * alarm behind its own timeout. */
+		sigemptyset(&none);
+		pthread_sigmask(SIG_SETMASK, &none, NULL);
+		dup2(agent_adv.fd[0], STDOUT_FILENO);
+		dup2(agent_adv.fd[1], STDERR_FILENO);
+		execvp(argv[0], argv);
+		_exit(127);
+	}
+	if (pid < 0) {
+		goto done;
+	}
+	/* Held as the sleeper's pid the instant it exists, so that a pre-empt
+	 * arriving now still finds it and kills it. */
+	pthread_mutex_lock(&agent_adv.mtx);
+	agent_adv.pid = pid;
+	pthread_mutex_unlock(&agent_adv.mtx);
+	setpgid(pid, pid);
+	while (waitpid(pid, &rc, 0) < 0 && errno == EINTR);
+	pthread_mutex_lock(&agent_adv.mtx);
+	agent_adv.pid = -1;
+	pthread_mutex_unlock(&agent_adv.mtx);
+	unlink(hdrpath);
+	unlink(bodypath);
+	*agent_adv.hdpath = '\0';
+	*st = WIFEXITED(rc) ? WEXITSTATUS(rc) : -1;
+	/* Whatever came back goes to the main thread to be read and logged:
+	 * on an error curl writes its complaint to stderr instead, and only
+	 * there is it worth a line of b-9. */
+	out = agent_adv_slurp(agent_adv.fd[0], (int)ADV_REPLY_MAX);
+	if (!out || !*out) {
+		free(out);
+		out = agent_adv_slurp(agent_adv.fd[1], 4096);
+	}
+	if (!out || !*out) {
+		free(out);
+		return NULL;
+	}
+	return out;
+done:
+	if (hf >= 0) {
+		close(hf);
+		unlink(hdrpath);
+	}
+	if (bf >= 0) {
+		close(bf);
+		unlink(bodypath);
+	}
+	if (*agent_adv.hdpath) {
+		unlink(agent_adv.hdpath);
+		*agent_adv.hdpath = 0;
+	}
+	free(body);
+	return NULL;
+}
+
+/* Drop what the sleeper holds: the spear is back and the entries are its
+ * again. agent_adv.mtx is held. */
+static void agent_adv_untake(void)
+{
+	for (int i = 0; i < agent_adv.nqueue; i++) {
+		free(agent_adv.queue[i].sys);
+		free(agent_adv.queue[i].prompt);
+		free(agent_adv.queue[i].prev);
+		free(agent_adv.queue[i].url);
+		free(agent_adv.queue[i].key);
+		free(agent_adv.queue[i].extra);
+	}
+	agent_adv.nqueue = 0;
+	agent_adv.want = 0;
+	agent_adv.awake = 0;
+}
+
+/* Whether the sleeper may take the next prompt without the main thread's
+ * leave: a quiet run is under way and prompts are queued, so the endpoint
+ * goes to the next answer at once instead of idling until the next scan.
+ * agent_adv.mtx is held. */
+static int agent_adv_go(void)
+{
+	return agent_adv.idle && !agent_adv.stop &&
+		agent_adv.primed == agent_adv.epoch && agent_adv.nqueue;
+}
+
+/* The sleeper thread. It waits while the spear owns the model, then after
+ * ADV_IDLE without a sign of work it rates one entry per request, oldest
+ * first, until the spear returns. The wait buys a quiet stretch, not each
+ * request: once the run has begun an answer is followed by the next
+ * submission, not by another ADV_IDLE. A request already sent is never
+ * cancelled: killing curl mid-answer would leave an entry half rated, so
+ * the entry goes back to the queue. */
+static void *agent_adv_worker(void *unused)
+{
+	struct timespec ts;
+	struct agent_adv_work w;
+	struct agent_adv_job j;
+	sigset_t all;
+	char *text;
+	int st, post, killed;
+	(void)unused;
+	sigfillset(&all);
+	pthread_sigmask(SIG_SETMASK, &all, NULL);
+	pthread_mutex_lock(&agent_adv.mtx);
+	for (;;) {
+		while (!agent_adv.quit && !agent_adv.awake && !agent_adv_go())
+			pthread_cond_wait(&agent_adv.cv, &agent_adv.mtx);
+		if (agent_adv.quit)
+			break;
+		if (agent_adv.stop) {
+			agent_adv_untake();
+			continue;
+		}
+		if (!agent_adv.idle) {
+			/* active, or the editor is not at its input: sleep
+			 * until either changes */
+			agent_adv.awake = 0;
+			continue;
+		}
+		if (agent_adv.primed != agent_adv.epoch) {
+			/* The quiet run starts here, once per stretch: spear
+			 * work bumps the epoch and this deadline is thrown away
+			 * with the run, so the sleeper only acts on a stretch that
+			 * went by unused. Past it primed says the run is under way,
+			 * and nothing waits between two requests. */
+			agent_adv.seen = agent_adv.epoch;
+			clock_gettime(CLOCK_REALTIME, &ts);
+			ts.tv_sec += ADV_IDLE / 1000;
+			ts.tv_nsec += (long)(ADV_IDLE % 1000) * 1000000;
+			if (ts.tv_nsec >= 1000000000) {
+				ts.tv_sec++;
+				ts.tv_nsec -= 1000000000;
+			}
+			while (!agent_adv.quit && !agent_adv.stop &&
+					agent_adv.epoch == agent_adv.seen)
+				if (pthread_cond_timedwait(&agent_adv.cv,
+						&agent_adv.mtx, &ts) ==
+						ETIMEDOUT)
+					break;
+			if (agent_adv.quit || agent_adv.stop ||
+					agent_adv.epoch != agent_adv.seen)
+				continue;
+			agent_adv.primed = agent_adv.seen;
+		}
+		if (!agent_adv.nqueue) {	/* it needs prompts */
+			agent_adv.want = 1;
+			agent_adv.awake = 0;
+			pthread_mutex_unlock(&agent_adv.mtx);
+			agent_adv_nudge();
+			pthread_mutex_lock(&agent_adv.mtx);
+			continue;
+		}
+		w = agent_adv.queue[0];
+		agent_adv.nqueue--;
+		if (agent_adv.nqueue)
+			memmove(agent_adv.queue, agent_adv.queue + 1,
+				agent_adv.nqueue * sizeof(*agent_adv.queue));
+		agent_adv.busy = 1;
+		agent_adv.num = w.n;
+		agent_adv.attempt = w.attempt;
+		pthread_mutex_unlock(&agent_adv.mtx);
+		text = agent_adv_ask(&w, &st);
+		pthread_mutex_lock(&agent_adv.mtx);
+		agent_adv.busy = 0;
+		agent_adv.awake = 0;
+		/* Ended by the editor's return: the entry was never answered, so
+		 * it goes back wanted and uncounted, with nothing said about it.
+		 * Counting it would give up on an entry only because the user
+		 * came back while it was being read. */
+		killed = agent_adv.killed;
+		agent_adv.killed = 0;
+		agent_adv.want = !text || killed;
+		j.n = w.n;
+		j.text = text;
+		j.st = st;
+		j.attempt = w.attempt;
+		post = !agent_adv.quit && !killed;
+		if (post && agent_adv.nout == ADV_OUT_MAX) {
+			free(j.text);
+			post = 0;
+		}
+		if (post) {
+			if (agent_adv.nout == agent_adv.omax) {
+				agent_adv.omax = agent_adv.omax ?
+					agent_adv.omax * 2 : 8;
+				agent_adv.out = erealloc(agent_adv.out,
+					agent_adv.omax * sizeof(*agent_adv.out));
+			}
+			agent_adv.out[agent_adv.nout++] = j;
+		}
+		pthread_mutex_unlock(&agent_adv.mtx);
+		free(w.sys);
+		free(w.prompt);
+		free(w.prev);
+		free(w.url);
+		free(w.key);
+		free(w.extra);
+		if (post)
+			agent_adv_nudge();
+	}
+	agent_adv_untake();
+	for (int i = 0; i < agent_adv.nout; i++)
+		free(agent_adv.out[i].text);
+	agent_adv.nout = 0;
+	pthread_mutex_unlock(&agent_adv.mtx);
+	return NULL;
+}
+
+/* Ask again about an entry whose answer did not parse: same entry, its
+ * previous answer back as an assistant turn. Built on the main thread. */
+static void agent_adv_requeue(unsigned long n, int attempt, const char *prev)
+{
+	struct agent_adv_work w;
+	w.n = n;
+	w.attempt = attempt;
+	w.timeout = request_timeout;
+	w.sys = agent_adv_sys(n);
+	w.prompt = agent_adv_prompt(n);
+	w.prev = prev && *prev ? sdup(prev, strlen(prev)) : NULL;
+	w.url = endpoint ? sdup(endpoint, strlen(endpoint)) : NULL;
+	w.key = api_key ? sdup(api_key, strlen(api_key)) : NULL;
+	w.extra = request_extra ?
+		sdup(request_extra, strlen(request_extra)) : NULL;
+	if (!w.sys || !w.prompt || !w.url || !w.key || !w.extra) {
+		free(w.sys);
+		free(w.prompt);
+		free(w.prev);
+		free(w.url);
+		free(w.key);
+		free(w.extra);
+		return;
+	}
+	pthread_mutex_lock(&agent_adv.mtx);
+	agent_adv_qadd(&w);
+	agent_adv.awake = 1;
+	pthread_cond_signal(&agent_adv.cv);
+	pthread_mutex_unlock(&agent_adv.mtx);
+}
+
+/* What the sleeper answered, oldest first: raw text to b-9, rating staged,
+ * another try while the entry is still worth asking. Main thread. */
+static void agent_adv_collect(void)
+{
+	struct agent_adv_job *js;
+	cJSON *root, *msg;
+	unsigned long n;
+	char *content;
+	int cnt, st, attempt, i;
+	pthread_mutex_lock(&agent_adv.mtx);
+	js = agent_adv.out;
+	cnt = agent_adv.nout;
+	agent_adv.out = NULL;
+	agent_adv.nout = agent_adv.omax = 0;
+	agent_adv.want = 0;
+	pthread_mutex_unlock(&agent_adv.mtx);
+	for (i = 0; i < cnt; i++) {
+		n = js[i].n;
+		st = js[i].st;
+		attempt = js[i].attempt;
+		/* The topic answer names the session; it rates nothing. */
+		if (n == ADV_NAME) {
+			agent_adv_name_reply(js[i].text, st, attempt);
+			free(js[i].text);
+			continue;
+		}
+		agent_adv.num = n;
+		agent_adv.attempt = attempt;
+		if (!js[i].text) {
+			if (st == 7) {
+				agent_adv_note("endpoint unreachable; "
+					":adv off for this session");
+				agent_adv.disabled = 1;
+				agent_adv_stop();
+				i++;	/* the rest are not looked at */
+				break;
+			}
+			agent_adv_note("no reply for entry %lu, status %d",
+				n, st);
+			if (attempt + 1 < ADV_ATTEMPTS)
+				agent_adv_requeue(n, attempt + 1, NULL);
+			else
+				agent_adv_note("no reply for %lu after %d "
+					"attempts; giving up", n,
+					ADV_ATTEMPTS);
+			free(js[i].text);
+			continue;
+		}
+		agent_adv_note("--- reply, entry %lu, attempt %d of %d, "
+			"status %d ---", n, attempt, ADV_ATTEMPTS, st);
+		agent_adv_log(js[i].text);
+		root = cJSON_ParseWithOpts(js[i].text, NULL, 1);
+		if (cJSON_GetObjectItem(root, "error")) {
+			char *em = cJSON_GetStringValue(cJSON_GetObjectItem(
+				cJSON_GetObjectItem(root, "error"),
+				"message"));
+			agent_adv_note("endpoint error: %s",
+				em ? em : "no message");
+			cJSON_Delete(root);
+			free(js[i].text);
+			continue;
+		}
+		content = NULL;
+		msg = agent_reply(root);
+		if (cJSON_IsString(cJSON_GetObjectItem(msg, "content")))
+			content = cJSON_GetObjectItem(msg,
+				"content")->valuestring;
+		agent_adv_parse(n, content);
+		/* The spear may have rated the entry itself or compacted it
+		 * away while the request ran. */
+		if (!agent_adv_wanted())
+			agent_adv_note("entry %lu already rated or gone; "
+				"nothing staged", n);
+		else if (agent_adv_staged_has(n))
+			agent_adv_note("staged the rating for entry %lu", n);
+		else if (attempt + 1 < ADV_ATTEMPTS) {
+			agent_adv_note("no rating for %lu; asking again", n);
+			agent_adv_requeue(n, attempt + 1, content);
+		}
+		else
+			agent_adv_note("no rating for %lu after %d attempts; "
+				"giving up", n, ADV_ATTEMPTS);
+		if (!agent_adv_staged_has(n) && attempt + 1 >= ADV_ATTEMPTS &&
+				agent_adv_wanted())
+			agent_adv_add(&agent_adv_gaveup, &agent_adv_ngaveup, n);
+		cJSON_Delete(root);
+		free(js[i].text);
+	}
+	for (; i < cnt; i++)	/* left over by a disabled endpoint */
+		free(js[i].text);
+	free(js);
+}
+
+static int agent_adv_staged_has(unsigned long n)
+{
+	for (int i = 0; i < agent_adv_nstaged; i++)
+		if (agent_adv_staged[i].n == n)
+			return 1;
+	return 0;
+}
+
+/* Stage the rating a reply carries. Models wrap the answer in prose, so
+ * lines that are not a rating are ignored, and markdown or the separators
+ * after a number are stripped. The entry number is advisory, the model
+ * echoing an earlier one as often as the one asked about: an exact match
+ * wins, and a reply with one rating for anything else is read as it. */
+static void agent_adv_parse(unsigned long want, const char *reply)
+{
+	char ln[2048], *p, *q, *d, *alt = NULL;
+	const char *s = reply, *text;
+	unsigned long n, altn = 0;
+	int len, rate, altrate = 0, nalt = 0, exact = 0;
+	while (s && *s) {
+		const char *nl = strchr(s, '\n');
+		len = nl ? (int)(nl - s) : (int)strlen(s);
+		if (len > (int)sizeof(ln) - 1)
+			len = sizeof(ln) - 1;
+		memcpy(ln, s, len);
+		ln[len] = '\0';
+		s = nl ? nl + 1 : NULL;
+		p = ln;
+		while (*p == ' ' || *p == '\t' || *p == '-' || *p == '*' ||
+				*p == '>' || *p == '`' || *p == '#')
+			p++;
+		n = strtoul(p, &q, 10);
+		if (q == p)
+			continue;
+		d = q;
+		while (*d == ' ' || *d == '\t' || *d == ':' || *d == '=' ||
+				*d == '*' || *d == '`' || *d == '.' || *d == ')')
+			d++;
+		if (!isdigit((unsigned char)*d) || d[1] > ' ')
+			d = NULL;
+		else if (*d > '3') {
+			agent_adv_note("entry %lu: rating %c is off the 0 to 3 "
+				"scale", want, *d);
+			continue;
+		}
+		/* "2 sentence": the rating with its entry number left off. */
+		if (!d && q == p + 1 && *p <= '3' && (*q == ' ' || *q == '\t')) {
+			d = p;
+			n = 0;
+		}
+		if (!d)
+			continue;
+		rate = *d - '0';
+		text = d + 1 + strspn(d + 1, " \t");
+		if (n == want) {
+			agent_adv_stage(want, rate, text);
+			exact = 1;
+			continue;
+		}
+		nalt++;
+		altrate = rate;
+		altn = n;
+		free(alt);
+		alt = sdup(text, strlen(text));
+	}
+	if (exact || nalt != 1) {
+		free(alt);
+		return;
+	}
+	/* The lone rating names an entry the model echoed instead, or it left
+	 * the number off: the entry asked about is the only other thing the
+	 * reply can mean, and asking again buys nothing. */
+	if (altn)
+		agent_adv_note("entry %lu: took its lone rating %d for "
+			"entry %lu", want, altrate, altn);
+	else
+		agent_adv_note("entry %lu: took its lone rating, which "
+			"names no entry", want);
+	agent_adv_stage(want, altrate, alt);
+	free(alt);
+}
+
+/* Whether the entry under review still wants a rating: the spear may have
+ * rated it, or a compaction dropped it, while the request ran. */
+static int agent_adv_wanted(void)
+{
+	struct agent_span *spans;
+	unsigned long floor = agent_epoch_floor();
+	int cnt = agent_spans(&spans), rate, row;
+	int keep = agent_adv.num >= floor &&
+		agent_span_rated(spans, cnt, agent_adv.num) &&
+		!agent_note(agent_adv.num, &rate, &row);
+	free(spans);
+	return keep;
+}
+
+/* A descriptor the main loop must never wait on. */
+static void agent_adv_nb(int fd)
+{
+	int fl = fcntl(fd, F_GETFL, 0);
+	if (fl >= 0)
+		fcntl(fd, F_SETFL, fl | O_NONBLOCK);
+}
+
+/* The input wait returned: take what the sleeper sent and, if the model is
+ * still free, give it more to do. */
+void agent_adv_service(void)
+{
+	char buf[64];
+	if (!agent_adv.on || agent_adv.disabled || agent_adv.stop)
+		return;
+	while (agent_adv.notify[0] >= 0 &&
+			read(agent_adv.notify[0], buf, sizeof(buf)) > 0);
+	agent_adv_collect();
+	if (!agent_adv.on || agent_adv.disabled || agent_adv.stop)
+		return;
+	pthread_mutex_lock(&agent_adv.mtx);
+	if (agent_adv.want || agent_adv.nqueue == 0)
+		agent_adv.awake = 1;
+	pthread_mutex_unlock(&agent_adv.mtx);
+	agent_adv_fill();
+	pthread_mutex_lock(&agent_adv.mtx);
+	if (agent_adv.nqueue)
+		agent_adv.awake = 1;
+	if (agent_adv.awake)
+		pthread_cond_signal(&agent_adv.cv);
+	pthread_mutex_unlock(&agent_adv.mtx);
+}
+
+/* Entering or leaving the input wait. Leaving is work of its own, so a
+ * request in flight is killed here rather than waited for: the session has
+ * the endpoint back the moment it wants it, and the worker reaps the child
+ * with the entry back on the queue. */
+void agent_adv_wait(int on)
+{
+	if (!agent_adv.on)
+		return;
+	/* A runner left behind by a ^Z answers while the editor is
+	 * stopped: what it answered is taken up here, so a rating the
+	 * model finished during the suspend is staged at the first wait
+	 * back and is never left sitting in a file. */
+	agent_adv_help_read();
+	pthread_mutex_lock(&agent_adv.mtx);
+	agent_adv.idle = on;
+	if (on) {
+		if (!agent_adv.stop && !agent_adv.disabled)
+			agent_adv.awake = 1;
+		pthread_cond_signal(&agent_adv.cv);
+	}
+	else {
+		agent_adv.epoch++;
+		agent_adv.awake = 0;
+		/* The session is back to its own work, so a request the sleeper
+		 * still has waiting is ended here rather than waited for: the
+		 * endpoint is the session's the moment it wants it. The worker
+		 * reaps it and drops the half answer; the entry is asked again
+		 * in the next downtime. The pid is read and cleared under the
+		 * mutex, so it is never a process that has already been reaped.
+		 */
+		if (agent_adv.pid > 0) {
+			agent_adv.killed = 1;
+			kill(-agent_adv.pid, SIGKILL);
+		}
+		pthread_cond_broadcast(&agent_adv.cv);
+	}
+	pthread_mutex_unlock(&agent_adv.mtx);
+}
+
+/* The self-pipe the input poll watches, or -1 when the sleeper is off. */
+int agent_adv_fd(void)
+{
+	return agent_adv.on && !agent_adv.disabled ? agent_adv.notify[0] : -1;
+}
+
+/* The spear used the model or the editor: the sleeper's quiet run has to
+ * start over from now. */
+void agent_adv_activity(void)
+{
+	pthread_mutex_lock(&agent_adv.mtx);
+	agent_adv.epoch++;
+	agent_adv.awake = 0;
+	pthread_cond_broadcast(&agent_adv.cv);
+	pthread_mutex_unlock(&agent_adv.mtx);
+}
+
+/* The spear is back: stop the sleeper and kill the request it has waiting.
+ * Called on input, on a tool, on a resume and when :adv goes off. */
+static void agent_adv_stop(void)
+{
+	pid_t pid;
+	pthread_mutex_lock(&agent_adv.mtx);
+	agent_adv.stop = 1;
+	agent_adv.idle = 0;
+	agent_adv.awake = 0;
+	agent_adv.epoch++;
+	pid = agent_adv.pid;
+	if (pid > 0)
+		agent_adv.killed = 1;
+	pthread_mutex_unlock(&agent_adv.mtx);
+	if (pid > 0)
+		kill(-pid, SIGKILL);
+}
+
+/* :adv on and off. */
+void agent_adv_toggle(int on)
+{
+	if (on)
+		agent_adv_start();
+	else
+		agent_adv_off();
+}
+
+#define ADV_HELP 4			/* requests a stopped editor may finish */
+
+/* A stopped editor cannot rate: SIGSTOP takes every thread, and ^Z reaches
+ * the curl child in the foreground group. So the quiet run goes on in a
+ * process of its own, in its own group, out of reach of both: it takes the
+ * prompts the sleeper had queued, waits, asks, and leaves each answer in a
+ * file; only the reading, the b-9 line and the staging wait for the return,
+ * which is the next input wait. Forked after the worker is joined, so the
+ * child copies a heap with one thread in it. */
+struct agent_adv_help {
+	pid_t pid;
+	int njob;
+	struct {
+		unsigned long n;
+		int attempt, got, timeout;
+		char path[64], out[64], st[64];
+	} j[ADV_HELP];
+};
+static struct agent_adv_help agent_help = { .pid = -1 };
+
+/* A string with its length first, so that newlines inside it mean nothing. */
+static void agent_adv_wstr(FILE *f, const char *s)
+{
+	size_t l = s ? strlen(s) : 0;
+	if (fprintf(f, "%zu\n", l) >= 0 && l)
+		fwrite(s, 1, l, f);
+}
+
+static char *agent_adv_rstr(FILE *f)
+{
+	size_t l;
+	char *s;
+	if (fscanf(f, "%zu", &l) != 1 || l > (size_t)ADV_REPLY_MAX)
+		return NULL;
+	if (!(s = malloc(l + 1)))
+		return NULL;
+	if (l && fread(s, 1, l, f) != l) {
+		free(s);
+		return NULL;
+	}
+	s[l] = '\0';
+	return s;
+}
+
+/* The runner's job: one entry, in a file only this user can read, which owns
+ * the name mkstemp made. */
+static int agent_adv_help_job(struct agent_adv_work *w, int i)
+{
+	struct agent_adv_help *h = &agent_help;
+	char tmpl[] = "/tmp/nextvi-advrun-XXXXXX";
+	FILE *f;
+	int fd = mkstemp(tmpl);
+	if (fd < 0)
+		return 0;
+	close(fd);
+	snprintf(h->j[i].path, sizeof(h->j[i].path), "%s", tmpl);
+	snprintf(h->j[i].out, sizeof(h->j[i].out), "%s.out", tmpl);
+	snprintf(h->j[i].st, sizeof(h->j[i].st), "%s.st", tmpl);
+	h->j[i].n = w->n;
+	h->j[i].attempt = w->attempt;
+	h->j[i].timeout = w->timeout;
+	h->j[i].got = 0;
+	if (!(f = fopen(tmpl, "w"))) {
+		unlink(tmpl);
+		return 0;
+	}
+	agent_adv_wstr(f, w->sys);
+	agent_adv_wstr(f, w->prompt);
+	agent_adv_wstr(f, w->prev);
+	agent_adv_wstr(f, w->url);
+	agent_adv_wstr(f, w->key);
+	agent_adv_wstr(f, w->extra);
+	fclose(f);
+	return 1;
+}
+
+/* What the sleeper's thread does with a prompt, done here instead: quiet
+ * first, then the request, then the answer where the editor will find it. */
+static void agent_adv_help_run(int n)
+{
+	struct timespec ts;
+	char num[24];
+	struct agent_adv_work j;
+	struct agent_adv_help *h = &agent_help;
+	FILE *f;
+	char *text;
+	int i, st, fd;
+	/* The fork shares the sleeper's curl file description and header name,
+	 * so the runner asks through temp files of its own, in its own group. */
+	agent_adv.fd[0] = agent_adv.fd[1] = -1;
+	*agent_adv.hdpath = 0;
+	setpgid(0, 0);
+	signal(SIGTTOU, SIG_IGN);
+	signal(SIGTTIN, SIG_IGN);
+	signal(SIGHUP, SIG_IGN);
+	signal(SIGINT, SIG_IGN);
+	for (i = 0; i < n; i++) {
+		ts.tv_sec = ADV_IDLE / 1000;
+		ts.tv_nsec = (long)(ADV_IDLE % 1000) * 1000000;
+		nanosleep(&ts, NULL);
+		if (!(f = fopen(h->j[i].path, "r")))
+			break;
+		j.n = h->j[i].n;
+		j.attempt = h->j[i].attempt;
+		j.timeout = h->j[i].timeout;
+		j.sys = agent_adv_rstr(f);
+		j.prompt = agent_adv_rstr(f);
+		j.prev = agent_adv_rstr(f);
+		j.url = agent_adv_rstr(f);
+		j.key = agent_adv_rstr(f);
+		j.extra = agent_adv_rstr(f);
+		fclose(f);
+		unlink(h->j[i].path);
+		text = j.sys && j.prompt && j.url && j.key ?
+			agent_adv_ask(&j, &st) : NULL;
+		if (text && (fd = open(h->j[i].out,
+				O_WRONLY | O_CREAT | O_TRUNC, 0600)) >= 0) {
+			agent_writeall(fd, text, strlen(text));
+			close(fd);
+		}
+		snprintf(num, sizeof(num), "%d\n", text ? st : -1);
+		if ((fd = open(h->j[i].st,
+				O_WRONLY | O_CREAT | O_TRUNC, 0600)) >= 0) {
+			agent_writeall(fd, num, strlen(num));
+			close(fd);
+		}
+		free(text);
+		free(j.sys);
+		free(j.prompt);
+		free(j.prev);
+		free(j.url);
+		free(j.key);
+		free(j.extra);
+	}
+	for (; i < n; i++)
+		unlink(h->j[i].path);
+	_exit(0);
+}
+
+/* Hand the queued prompts to a runner of its own and let the sleeper rest:
+ * while the editor is stopped the runner is the only thing that asks. */
+void agent_adv_suspend(void)
+{
+	struct agent_adv_help *h = &agent_help;
+	struct agent_adv_work take[ADV_HELP];
+	int i, n = 0;
+	if (!agent_adv.on || agent_adv.disabled || h->pid > 0)
+		return;
+	agent_adv_fill();
+	pthread_mutex_lock(&agent_adv.mtx);
+	n = (int)(sizeof(take) / sizeof(*take));
+	if (n > agent_adv.nqueue)
+		n = agent_adv.nqueue;
+	for (i = 0; i < n; i++) {
+		if (!agent_adv_help_job(&agent_adv.queue[i], i))
+			break;
+		take[i] = agent_adv.queue[i];
+	}
+	n = i;
+	h->njob = n;
+	agent_adv.nqueue -= n;
+	if (agent_adv.nqueue)
+		memmove(agent_adv.queue, agent_adv.queue + n,
+			agent_adv.nqueue * sizeof(*agent_adv.queue));
+	pthread_mutex_unlock(&agent_adv.mtx);
+	agent_adv_stop();
+	agent_adv_halt();	/* one thread left when the child is forked */
+	if (n <= 0)
+		return;
+	h->pid = fork();
+	if (!h->pid)
+		agent_adv_help_run(n);	/* does not return */
+	if (h->pid < 0)
+		agent_adv_help_drop();
+	else
+		setpgid(h->pid, h->pid);
+	for (i = 0; i < n; i++) {	/* the child has a copy of its own */
+		free(take[i].sys);
+		free(take[i].prompt);
+		free(take[i].prev);
+		free(take[i].url);
+		free(take[i].key);
+		free(take[i].extra);
+	}
+}
+
+/* Kill the runner and its group and remove what it left; an entry it never
+ * got to is unrated, as after a pre-empt. */
+static void agent_adv_help_drop(void)
+{
+	struct agent_adv_help *h = &agent_help;
+	int i;
+	if (h->pid <= 0)
+		return;
+	kill(-h->pid, SIGKILL);
+	waitpid(h->pid, NULL, 0);
+	for (i = 0; i < h->njob; i++) {
+		unlink(h->j[i].path);
+		unlink(h->j[i].out);
+		unlink(h->j[i].st);
+	}
+	h->pid = -1;
+	h->njob = 0;
+}
+
+/* Answers the runner left behind: staged at the first wait back, like an
+ * answer from the sleeper's own thread. */
+static void agent_adv_help_read(void)
+{
+	struct agent_adv_help *h = &agent_help;
+	struct agent_adv_job j;
+	char num[24];
+	FILE *f;
+	int i, fd, gone;
+	if (h->pid <= 0)
+		return;
+	gone = waitpid(h->pid, NULL, WNOHANG) != 0;
+	for (i = 0; i < h->njob; i++) {
+		if (h->j[i].got || !(f = fopen(h->j[i].st, "r")))
+			continue;
+		if (fscanf(f, "%23s", num) != 1)
+			*num = '\0';
+		fclose(f);
+		j.n = h->j[i].n;
+		j.attempt = h->j[i].attempt;
+		j.st = *num ? atoi(num) : -1;
+		j.text = NULL;
+		if ((fd = open(h->j[i].out, O_RDONLY)) >= 0) {
+			j.text = agent_adv_slurp(fd, (int)ADV_REPLY_MAX);
+			close(fd);
+		}
+		unlink(h->j[i].out);
+		unlink(h->j[i].st);
+		h->j[i].got = 1;
+		pthread_mutex_lock(&agent_adv.mtx);
+		if (agent_adv.nout < ADV_OUT_MAX) {
+			if (agent_adv.nout == agent_adv.omax) {
+				agent_adv.omax = agent_adv.omax ?
+					agent_adv.omax * 2 : 8;
+				agent_adv.out = erealloc(agent_adv.out,
+					agent_adv.omax *
+					sizeof(*agent_adv.out));
+			}
+			agent_adv.out[agent_adv.nout++] = j;
+		}
+		else
+			free(j.text);
+		pthread_mutex_unlock(&agent_adv.mtx);
+	}
+	if (!gone)
+		return;
+	for (i = 0; i < h->njob; i++)
+		if (!h->j[i].got) {
+			unlink(h->j[i].path);
+			unlink(h->j[i].out);
+			unlink(h->j[i].st);
+		}
+	h->pid = -1;
+	h->njob = 0;
+}
+
+/* Back from a suspend: the runner's answers are taken at the input wait
+ * itself, so all that is left is to give the sleeper its thread again. */
+void agent_adv_resume(void)
+{
+	if (agent_adv.on)
+		agent_adv_start();
+}
+
+/* Take the model back: the sleeper sleeps again and everything it holds is
+ * dropped, because an entry it never asked about is the spear's to rate. */
+void agent_adv_preempt(void)
+{
+	if (!agent_adv.on)
+		return;
+	/* a runner from a ^Z gives the endpoint back the same way:
+	 * an entry it never got to is the spear's to rate. */
+	agent_adv_help_drop();
+	agent_adv_stop();
+}
+
+/* Start the sleeper once per session; :adv may be turned off and on again
+ * without another thread. */
+int agent_adv_start(void)
+{
+	if (agent_adv.notify[1] < 0 && pipe(agent_adv.notify))
+		return 0;
+	agent_adv_nb(agent_adv.notify[0]);
+	if (!agent_adv.thread) {
+		agent_adv.stop = 0;
+		agent_adv.disabled = 0;
+		agent_adv.quit = 0;	/* halt left it set: the thread would exit */
+		if (pthread_create(&agent_adv.td, NULL, agent_adv_worker,
+				NULL))
+			return 0;
+		agent_adv.thread = 1;
+	}
+	agent_adv.on = 1;
+	agent_adv.stop = 0;
+	pthread_mutex_lock(&agent_adv.mtx);
+	agent_adv.awake = 1;
+	agent_adv.seen = agent_adv.epoch;
