+/* :adv off, and exit. */
+void agent_adv_off(void)
+{
+	agent_adv.on = 0;
+	/* :adv off leaves nothing asking behind, runner included */
+	agent_adv_help_drop();
+	agent_adv_stop();
+	agent_adv_clear();
+}
+
+void agent_adv_halt(void)
+{
+	/* a runner left by a ^Z is not left running behind the editor */
+	agent_adv_help_drop();
+	if (!agent_adv.thread)
+		return;
+	pthread_mutex_lock(&agent_adv.mtx);
+	agent_adv.quit = 1;
+	agent_adv.awake = 1;
+	pthread_cond_broadcast(&agent_adv.cv);
+	pthread_mutex_unlock(&agent_adv.mtx);
+	if (agent_adv.pid > 0)
+		kill(-agent_adv.pid, SIGKILL);
+	pthread_join(agent_adv.td, NULL);
+	agent_adv.thread = 0;
+}
